extras.css:
/* ═══════════ المُذهَّب — على هيئة المصاحف والمخطوطات السلطانية ═══════════ */
:root {
  --lap: #1B3768; --lapd: #11254A; --gold: #B8913F; --goldl: #E3C77C; --ink: #2A1F14; --cream: color-mix(in srgb, #F1E2B4 22%, var(--paper)); --carm: #9A2A1E;
}

/* ١) الجدول: إطار مذهّب حول النص (سلسلة معيّنات بين خطين، وزوايا بوردة، وخيط داخلي) */
.jd {
  position: absolute;
  top: calc(var(--m-top) - 8mm); bottom: calc(var(--m-bottom) - 9mm);
  left: calc(var(--t-l) - 8mm); right: calc(var(--t-r) - 8mm);
  border: .45pt solid var(--lap);
  background-image: asset(corner), asset(corner), asset(corner), asset(corner), asset(bandh), asset(bandh), asset(bandv), asset(bandv);
  background-position: left 1.2mm top 1.2mm, right 1.2mm top 1.2mm, left 1.2mm bottom 1.2mm, right 1.2mm bottom 1.2mm, center top 1.2mm, center bottom 1.2mm, left 1.2mm center, right 1.2mm center;
  background-size: 1.8mm 1.8mm, 1.8mm 1.8mm, 1.8mm 1.8mm, 1.8mm 1.8mm, calc(100% - 6mm) 1.8mm, calc(100% - 6mm) 1.8mm, 1.8mm calc(100% - 6mm), 1.8mm calc(100% - 6mm);
  background-repeat: no-repeat;
}
.jd::after { content: ''; position: absolute; inset: 3.75mm; border: .4pt solid var(--gold); }
/* نصوص الهامش وخاناتها خارج الجدول لا عليه (بُعد الجدول عن النص + فسحة) */
.page.content, .page.toc { --mside-clear: 9mm; }
/* وخانات الهامش (١٣) فوق الشريط السفلي للجدول ونجمة الرقم، وفي الهامش الواسع بعيدةٌ عن حافة القصّ */
.page.content, .page.toc { --mside-bottom: 18.5mm; }
#book.om-wide .page.content, #book.om-wide .page.toc { --mside-edge: 6.5mm; }
/* خط الهامش: مسطرة رفيعة في الطرف الخارجي */
.hmx { position: absolute; top: calc(var(--m-top) - 8mm); bottom: calc(var(--m-bottom) - 9mm); width: 0; border-left: .4pt solid var(--lap); }
.page.pg-l .hmx { left: calc(var(--t-l) - 11.5mm); }
.page.pg-r .hmx { right: calc(var(--t-r) - 11.5mm); }
/* (صفحةٌ كُتب في هامشها الخارجي: المسطرة تُخلي موضعها للكتابة) */
.page.pg-l:has(> .mside-n.l) .hmx, .page.pg-r:has(> .mside-n.r) .hmx { display: none; }

/* ٢) الترويسة: خرطوشة مركّبة على الشريط العلوي للجدول */
.rh { top: calc(var(--m-top) - 9.1mm); left: var(--t-l); right: var(--t-r); height: 6.4mm; padding: 0; border: 0; overflow: visible; line-height: 1; text-align: center; }
.rhc { display: inline-flex; align-items: center; justify-content: center; position: relative; height: 6.4mm; max-width: 96mm; padding: 0 6mm;
  background: var(--cream); border: .5pt solid var(--gold); border-radius: 3.2mm;
  box-shadow: 0 0 0 .55mm var(--paper), 0 0 0 .8mm var(--lap), 0 0 0 1.5mm var(--paper); }
.rhc-t { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: var(--f-heading); font-weight: 700; font-size: 9.5pt; line-height: 1.6; color: var(--c-h2); }
.rhc::before, .rhc::after { content: ''; position: absolute; top: 50%; width: 1.5mm; height: 1.5mm; margin-top: -.75mm; background: var(--gold); transform: rotate(45deg); }
.rhc::before { right: 2.2mm; } .rhc::after { left: 2.2mm; }

/* ٣) رقم الصفحة: نجمة ثمانية مرصّعة في الشريط السفلي للجدول */
.folio { bottom: calc(var(--m-bottom) - 12.5mm); left: var(--t-l); right: var(--t-r); height: 11.2mm; line-height: 1; }
.fo { display: inline-flex; align-items: center; justify-content: center; width: 11.2mm; height: 11.2mm; padding-top: .5mm;
  background: asset(fstar) center / 100% 100% no-repeat; color: var(--c-h1); font-family: var(--f-heading); font-weight: 700; font-size: 9.5pt; }

/* ٤) التعقيبة: أول كلمة من الصفحة التالية في ذيل الصفحة اليسرى، كما في المخطوطات */
.tq { position: absolute; bottom: calc(var(--m-bottom) - 16.5mm); left: calc(var(--t-l) - 7mm); font-family: var(--f-body); font-size: 10pt; line-height: 1.4; color: #6A5845; transform: rotate(-5deg); transform-origin: left center; }

/* ٥) السرلوح: رأس الباب — عُرف من قباب مذهّبة، لوح لازوردي منقوش، خرطوشة فيها اسم الباب، وذؤابة تمتد إلى ترنجة في الهامش برقم الباب */
.h1 { margin: 0 0 7.5mm; padding-top: 1.5mm; line-height: 1.5; }
.h1::after { display: none; }
.srl { position: relative; }
.srl-cr { display: block; height: 4.2mm; margin: 0 1.6mm -.15mm; background: asset(crestrow) center bottom / 100% 4.2mm no-repeat; }
.srl-p { position: relative; padding: 3.6mm 11mm; border: .5pt solid var(--ink);
  background: asset(panel) center / 100% 100% no-repeat var(--lap);
  box-shadow: inset 0 0 0 .9mm var(--gold), inset 0 0 0 1.1mm var(--ink), inset 0 0 0 1.6mm var(--lapd); }
.srl-c { position: relative; display: flex; align-items: center; justify-content: center; min-height: 11.5mm; padding: .4mm 7mm;
  background: var(--cream); border: .6pt solid var(--gold); border-radius: 7mm;
  box-shadow: 0 0 0 .55mm var(--lapd), 0 0 0 .85mm var(--gold); }
.srl-t { font-family: var(--f-heading); color: var(--c-h1); }
.tp { position: absolute; top: 50%; width: 4.2mm; height: 8mm; margin-top: -4mm; background: asset(tip) center / 100% 100% no-repeat; }
.tp.tpa { right: calc(100% + .5mm); }
.tp.tpb { left: calc(100% + .5mm); transform: scaleX(-1); }
.srl-fin { position: absolute; top: 50%; width: 11.5mm; height: 5mm; margin-top: -2.5mm; background: asset(fin) center / 100% 100% no-repeat; }
.srl-md { position: absolute; top: 50%; width: 12.6mm; height: 12.6mm; margin-top: -6.3mm; display: flex; align-items: center; justify-content: center;
  background: asset(medal) center / 100% 100% no-repeat; font-style: normal; }
.srl-md b { font-family: var(--f-heading); font-weight: 700; font-size: 8.5pt; line-height: 1; color: var(--c-h2); padding-top: .4mm; }
.page.pg-l .srl-fin { right: 100%; transform: scaleX(-1); }
.page.pg-r .srl-fin { left: 100%; }
.page.pg-l .srl-md { right: calc(100% + 11.5mm - 6.3mm); }
.page.pg-r .srl-md { left: calc(100% + 11.5mm - 6.3mm); }
/* صفحةٌ في هامشها الخارجي كتابة: الذؤابة والترنجة لا تزاحمانها */
#book:not(.om-wide):not(.mu-side) .page.pg-l:has(> .mside-n.l) .srl-fin, #book:not(.om-wide):not(.mu-side) .page.pg-l:has(> .mside-n.l) .srl-md,
#book:not(.om-wide):not(.mu-side) .page.pg-r:has(> .mside-n.r) .srl-fin, #book:not(.om-wide):not(.mu-side) .page.pg-r:has(> .mside-n.r) .srl-md { display: none; }
/* الهامش الواسع والهامش بجانب المتن: الترنجة برقم الباب داخل اللوح في طرفه الخارجي (فالهامش للكتابة) */
#book.om-wide .srl-fin, #book.mu-side .srl-fin { display: none; }
#book.om-wide .srl-p { padding-left: 17mm; padding-right: 17mm; }
#book.mu-side .srl-p { padding-left: 10mm; padding-right: 10mm; }
#book.mu-side .srl-c { padding-left: 3mm; padding-right: 3mm; }
#book.mu-side .tp { display: none; }
#book.om-wide .srl-md, #book.mu-side .srl-md { width: 10mm; height: 10mm; margin-top: -5mm; }
#book.mu-side .srl-md { width: 8.4mm; height: 8.4mm; margin-top: -4.2mm; }
#book.mu-side .srl-md b { font-size: 7.5pt; }
#book.om-wide .page.pg-l .srl-md, #book.mu-side .page.pg-l .srl-md { left: 2.6mm; right: auto; }
#book.mu-side .page.pg-l .srl-md { left: 1mm; }
#book.om-wide .page.pg-r .srl-md, #book.mu-side .page.pg-r .srl-md { right: 2.6mm; left: auto; }
#book.mu-side .page.pg-r .srl-md { right: 1mm; }

/* ٦) الفصل: بالحمرة بين ذراعين مذهّبتين */
.h2 { margin: 6mm 0 4mm; }
.fs { display: flex; align-items: center; gap: 2.4mm; }
.fs-t { flex: 0 1 auto; max-width: 80%; }
.fs-a { flex: 1 1 0; min-width: 8mm; height: 4.4mm; background: asset(arm) left center / auto 100% no-repeat; }
.fs-a.fsb { transform: scaleX(-1); }

/* ٧) العنوان الفرعي بوردة مذهّبة، والرابع بمعيّن */
.h3 { margin: 4.5mm 0 2.4mm; }
.h3m { display: inline-block; width: 3.7mm; height: 3.7mm; margin-inline-end: 1.8mm; vertical-align: -.35mm; background: asset(rose) center / contain no-repeat; }
.h4m { display: inline-block; width: 1.7mm; height: 1.7mm; margin-inline-end: 2mm; vertical-align: .6mm; background: var(--gold); border: .3pt solid var(--ink); transform: rotate(45deg); }

/* ٨) الفاصل الزخرفي، وفاصل الشطرين، وعلامات الحواشي */
.orn { margin: 3mm 0 4mm; line-height: 0; }
.ornt { display: block; height: 7.5mm; background: asset(tail) center / contain no-repeat; }
.verse > .vsep, .fnv > .vsep { color: transparent; min-width: 4.4mm; background: asset(rose) center / 3.3mm 3.3mm no-repeat; }
.verse > .vsep.vmid { color: var(--c-h2); background: none; }
.fnsep { width: 42mm; height: 2.4mm; border-top: 0; margin: 0 0 1.3mm; background: asset(fnsep) right center / 42mm 2.4mm no-repeat; }
.fn .fnn { color: var(--c-h2); }
.fr { color: var(--c-h2); }

/* في كتب «المتن أعلى الصفحة والشرح تحته»: الخط بين القسمين بعرض الصفحة، وطرفه معيّن مذهّب */
.notes.sh .fnsep { width: 100%; background: asset(fnsep) right center / 42mm 2.4mm no-repeat, linear-gradient(var(--gold), var(--gold)) left center / calc(100% - 41mm) .5pt no-repeat; }

/* ٩) الفهرس */
.tch { padding-top: 1mm; margin-bottom: 4mm; }
.tch .srl-p { padding: 3mm 14mm; }
.tch .srl-t { font-size: 20pt; line-height: 1.5; font-weight: 700; }
.tch .toc-head { margin: 4mm 0 1.5mm; padding-bottom: 1mm; border-bottom: .5pt solid var(--gold); font-family: var(--f-heading); font-size: 11.5pt; color: var(--c-h2); }
.toc-e .ld { color: var(--gold); }
.toc-e .n { color: var(--c-h1); }
.toc-e.l1 { margin-top: 2mm; }
.toc-e.l1 .t::before { content: ''; display: inline-block; width: 3mm; height: 3mm; margin-inline-end: 1.6mm; vertical-align: -.2mm; background: asset(rose) center / contain no-repeat; }
.toc-e.l2 .t::before { content: ''; display: inline-block; width: 1.3mm; height: 1.3mm; margin-inline-end: 1.8mm; vertical-align: .6mm; background: var(--gold); transform: rotate(45deg); }

/* ١٠) الغلاف الداخلي: ترنجة مشعّة فيها العنوان، بين أذنين، داخل الجدول */
.page.cover .body { top: 0; bottom: 0; left: 0; right: 0; }
.cvx { position: absolute; inset: 0; }
.cvx-in { position: absolute; top: 30mm; bottom: 29mm; left: calc(24mm + var(--g-l)); right: calc(24mm + var(--g-r)); display: flex; flex-direction: column; align-items: center; justify-content: space-between; text-align: center; }
.cvx-vol { position: absolute; top: 15.6mm; left: var(--g-l); right: var(--g-r); text-align: center; line-height: 1; }
.cvx-vol span { display: inline-flex; align-items: center; height: 6.8mm; padding: 0 7mm; background: var(--cream); border: .5pt solid var(--gold); border-radius: 3.4mm;
  box-shadow: 0 0 0 .55mm var(--paper), 0 0 0 .8mm var(--lap), 0 0 0 1.5mm var(--paper); font-family: var(--f-heading); font-weight: 700; font-size: 11pt; color: var(--c-h1); }
.cvx-hd { width: 84%; }
.cvx-hd .srl-p { height: 9mm; padding: 0; }
.cvx-hd .srl-p::after { content: ''; position: absolute; left: 50%; top: 50%; width: 13mm; height: 13mm; margin: -6.5mm 0 0 -6.5mm; background: asset(rose) center / 4.6mm 4.6mm no-repeat, asset(medal) center / 100% 100% no-repeat; }
.cvx-mid { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; width: 100%; }
.tranj { position: relative; z-index: 0; width: 100mm; max-width: 100%; padding: 14mm 12mm; margin: 15mm 0 15mm; border-radius: 50%;
  background: asset(ground) center / 100% 100% no-repeat var(--cream); border: .7pt solid var(--gold);
  box-shadow: 0 0 0 .9mm var(--paper), 0 0 0 1.25mm var(--lap), 0 0 0 1.55mm var(--paper), 0 0 0 1.95mm var(--gold); }
.tranj-r { position: absolute; z-index: -1; inset: -9mm -10mm; background: asset(rays) center / 100% 100% no-repeat; }
.pend { position: absolute; left: 50%; width: 15mm; height: 12.2mm; margin-left: -7.5mm; background: asset(pend) center / 100% 100% no-repeat; }
.pend.pu { bottom: calc(100% + 1.6mm); }
.pend.pd { top: calc(100% + 1.6mm); transform: scaleY(-1); }
.cvx-title { font-family: var(--f-cover); font-weight: 700; font-size: 29pt; line-height: 1.45; color: var(--c-h1); }
.cvx-sub { font-family: var(--f-heading); font-weight: 700; font-size: 14pt; line-height: 1.6; color: var(--c-h2); margin-top: 1.5mm; }
.cvx-lbl { display: flex; align-items: center; gap: 2.5mm; font-family: var(--f-heading); font-weight: 700; font-size: 10.5pt; color: var(--gold); line-height: 1.8; }
.cvx-lbl::before, .cvx-lbl::after { content: ''; width: 9mm; border-top: .5pt solid var(--gold); }
.cvx-author { font-family: var(--f-names); font-weight: 700; font-size: 19pt; line-height: 1.6; color: var(--c-h2); }
.cvx-note { font-size: 10.5pt; color: #5b4a3c; line-height: 1.5; }
.cvx-ed { margin-top: 4.5mm; }
.cvx-editor { font-family: var(--f-names); font-weight: 700; font-size: 15pt; line-height: 1.6; color: var(--c-h1); }
.cvx-bot { font-family: var(--f-heading); font-size: 10.5pt; line-height: 1.7; color: #4a3a2e; }
.cvx-tl { display: block; width: 46mm; height: 6.5mm; margin: 0 auto 1.5mm; background: asset(tail) center / contain no-repeat; }
.cvx-pub { font-weight: 700; color: var(--c-h1); }

/* صفحة العنوان المختصر في النسخة الجاهزة للطباعة: ذيل مذهّب تحت العنوان */
.page.front-half .ht-box::after { content: ''; display: block; width: 44mm; height: 6.2mm; margin: 3mm auto 0; background: asset(tail) center / contain no-repeat; }

/* ١١) صفحة البسملة: شمسة مشعّة */
.bsx { position: absolute; inset: 0; }
.bsx-sh { position: absolute; left: calc(50% - var(--page-w) * .34 + (var(--g-l) - var(--g-r)) / 2); top: calc(46% - var(--page-w) * .34); width: calc(var(--page-w) * .68); height: calc(var(--page-w) * .68); display: flex; align-items: center; justify-content: center;
  background: asset(shamsa) center / 100% 100% no-repeat; }
.bsx-b { font-family: 'Scheherazade New', var(--f-heading); font-size: calc(var(--page-w) * .145); line-height: 1; color: var(--c-h1); padding-bottom: 2mm; }

/* ١٢) الخاتمة: حرد المتن على هيئة المثلث المقلوب */
.khx { position: absolute; inset: 0; }
.khx-in { position: absolute; top: 30%; left: calc(22mm + var(--g-l)); right: calc(22mm + var(--g-r)); display: flex; flex-direction: column; align-items: center; text-align: center; }
.khx-t { display: block; width: 50mm; height: 7mm; margin-bottom: 5mm; background: asset(tail) center / contain no-repeat; }
.khx-l { font-family: var(--f-heading); font-size: calc(var(--page-w) * .031); line-height: 2; color: var(--c-text); white-space: nowrap; }
.khx-l.k1 { color: var(--c-h2); font-weight: 700; font-size: calc(var(--page-w) * .033); }
.khx-l.k6 { color: var(--c-h2); font-weight: 700; }
.khx-r { display: block; width: 5.5mm; height: 5.5mm; margin-top: 2.5mm; background: asset(rose) center / contain no-repeat; }
.khx-b { margin-top: 6mm; font-family: var(--f-heading); font-weight: 700; font-size: 11pt; line-height: 1.7; color: var(--c-h1); }

/* ١٣) خانة الهامش: ما يُكتب في الهامش في خانةٍ على هيئة الجدول — سلسلة المعيّنات بين خطّين، وزوايا بوردة، وخيطٌ مذهّب،
   ووردةٌ على حافتها التي تلي النص. بقدر ما كُتب فيها: تكبر بكبره، ولا تظهر إلا حيث كُتب (sideNote.box) */
:root { --c-owner-ink: #A88B4E; }
#book .mside-n.framed { padding: 3.4mm 3.7mm 3.1mm; border: .45pt solid var(--lap); border-radius: 0; background-color: var(--cream);
  background-image: asset(corner), asset(corner), asset(corner), asset(corner), asset(bandh), asset(bandh), asset(bandv), asset(bandv);
  background-position: left .9mm top .9mm, right .9mm top .9mm, left .9mm bottom .9mm, right .9mm bottom .9mm, center top .9mm, center bottom .9mm, left .9mm center, right .9mm center;
  background-size: 1.8mm 1.8mm, 1.8mm 1.8mm, 1.8mm 1.8mm, 1.8mm 1.8mm, calc(100% - 5.4mm) 1.8mm, calc(100% - 5.4mm) 1.8mm, 1.8mm calc(100% - 5.4mm), 1.8mm calc(100% - 5.4mm);
  background-repeat: no-repeat; box-shadow: none; }
#book .mside-n.framed::before { content: ''; position: absolute; inset: 3mm; border: .4pt solid var(--gold); pointer-events: none; }
#book .mside-n.framed::after { content: ''; position: absolute; top: calc(50% - 1.9mm); width: 3.8mm; height: 3.8mm; pointer-events: none;
  background: asset(rose) center / contain no-repeat; }
#book .mside-n.framed.l::after { right: -1.9mm; }   /* في هامش اليسار: الوردة على حافتها اليمنى، تلي النص */
#book .mside-n.framed.r::after { left: -1.9mm; }
/* الهامش العادي ضيّق: الخانة نفسها أرقّ (خطٌّ لازوردي وخيطٌ مذهّب وزوايا)، ليبقى للكتابة عرضها */
#book:not(.om-wide) .mside-n.framed { padding: 1.5mm 1.6mm 1.3mm;
  background-image: asset(corner), asset(corner), asset(corner), asset(corner);
  background-position: left .35mm top .35mm, right .35mm top .35mm, left .35mm bottom .35mm, right .35mm bottom .35mm;
  background-size: 1.2mm 1.2mm, 1.2mm 1.2mm, 1.2mm 1.2mm, 1.2mm 1.2mm; }
#book:not(.om-wide) .mside-n.framed::before { inset: .8mm; }
#book:not(.om-wide) .mside-n.framed::after { width: 2.6mm; height: 2.6mm; top: calc(50% - 1.3mm); }
#book:not(.om-wide) .mside-n.framed.l::after { right: -1.3mm; }
#book:not(.om-wide) .mside-n.framed.r::after { left: -1.3mm; }

/* ١٤) خانات صاحب النسخة في الغلاف الداخلي: إطارٌ على هيئة الجدول، والغلاف يتقارب لها */
.cv-owner { width: 86%; margin: 2mm auto 3.5mm; padding: 5.2mm 6.8mm 4.4mm; gap: 4.6mm 2.5mm; font-family: var(--f-heading); font-size: 12pt; color: var(--c-h2);
  border: .45pt solid var(--lap); background-color: var(--cream);
  background-image: asset(corner), asset(corner), asset(corner), asset(corner), asset(bandh), asset(bandh), asset(bandv), asset(bandv);
  background-position: left .9mm top .9mm, right .9mm top .9mm, left .9mm bottom .9mm, right .9mm bottom .9mm, center top .9mm, center bottom .9mm, left .9mm center, right .9mm center;
  background-size: 1.8mm 1.8mm, 1.8mm 1.8mm, 1.8mm 1.8mm, 1.8mm 1.8mm, calc(100% - 5.4mm) 1.8mm, calc(100% - 5.4mm) 1.8mm, 1.8mm calc(100% - 5.4mm), 1.8mm calc(100% - 5.4mm);
  background-repeat: no-repeat; }
.page.cover.has-owner .cvx-in { top: 27mm; bottom: 25mm; }
.page.cover.has-owner .tranj { margin: 8mm 0 9mm; padding: 10mm 11mm; }
.page.cover.has-owner .cvx-title { font-size: 25pt; }
.page.cover.has-owner .cvx-ed { margin-top: 2.5mm; }

/* ١٥) المتون */
/* «قبل المتن» («قال المصنف…»): خرطوشةٌ مذهّبة كخرطوشة الترويسة — لوحٌ كريمي بخيطٍ مذهّب وطوقٍ لازوردي، ومعيّنٌ مذهّب في كل طرف */
.mintro > span { position: relative; display: inline-block; padding: .5mm 7.2mm .8mm; background: var(--cream); border: .5pt solid var(--gold); border-radius: 4mm;
  box-shadow: 0 0 0 .55mm var(--paper), 0 0 0 .8mm var(--lap); }
.mintro > span::before, .mintro > span::after { content: ''; position: absolute; top: 50%; width: 1.5mm; height: 1.5mm; margin: -.75mm 0 0; background: var(--gold); transform: rotate(45deg); }
.mintro > span::before { right: 2.4mm; } .mintro > span::after { left: 2.4mm; }
.mintro { margin: 1.5mm 1mm 2.6mm; }
/* عنوان التعليق: خرطوشةٌ كريمية بطوقٍ لازوردي، وفيها الاسم بين وردتين */
.mc-label > span { display: inline-block; padding: .3mm 4mm .6mm; background: var(--cream); border: .6pt solid var(--gold); border-radius: 5mm;
  box-shadow: 0 0 0 .5mm var(--lapd), 0 0 0 .8mm var(--gold); }
.mc-label > span::before, .mc-label > span::after { content: ''; display: inline-block; font-size: inherit; font-weight: 400; color: transparent;
  width: .62em; height: .62em; margin: 0 2.2mm; vertical-align: .02em; background: asset(rose) center / contain no-repeat; }
.mc-label { margin-top: 1mm; }
/* التعليق تحت المتن: ذيلٌ مذهّب يفصله عن المتن (ولا يتكرر بعد الفاصل الزخرفي) */
.msep { border-top: 0; height: 6mm; margin: 1mm 0 3mm; background: asset(tail) center / auto 100% no-repeat; }
.orn + .mc-below > .msep { height: 0; margin: 0 0 2mm; background: none; }
/* صفحة التعليق المقابلة: موضع الكتابة جدولٌ مذهّب كجدول النص — سلسلة المعيّنات بين خطين، وزوايا بوردة، وخيطٌ مذهّب */
.page.mcom .mc { position: relative; padding: 5.2mm 5mm 4.6mm; border: .45pt solid var(--lap);
  background-image: asset(corner), asset(corner), asset(corner), asset(corner), asset(bandh), asset(bandh), asset(bandv), asset(bandv);
  background-position: left 1mm top 1mm, right 1mm top 1mm, left 1mm bottom 1mm, right 1mm bottom 1mm, center top 1mm, center bottom 1mm, left 1mm center, right 1mm center;
  background-size: 1.8mm 1.8mm, 1.8mm 1.8mm, 1.8mm 1.8mm, 1.8mm 1.8mm, calc(100% - 5.6mm) 1.8mm, calc(100% - 5.6mm) 1.8mm, 1.8mm calc(100% - 5.6mm), 1.8mm calc(100% - 5.6mm);
  background-repeat: no-repeat; }
.page.mcom .mc::before { content: ''; position: absolute; inset: 3.5mm; border: .4pt solid var(--gold); pointer-events: none; }
/* الهامش بجانب المتن: سلسلة المعيّنات قائمةً بين المتن والتعليق */
.mside-right .mc-side::after, .mside-left .mc-side::after { border: 0; width: 1.8mm; background: asset(bandv) center / 100% 100% no-repeat; }
.mside-right .mc-side::after { right: -3.4mm; }
.mside-left .mc-side::after { left: -3.4mm; }
/* أرقام الأبيات بالحمرة */
.verse > .vno { color: var(--c-h2); border-inline-end-color: color-mix(in srgb, var(--gold) 70%, transparent); }

/* ١٦) إن اختار المستخدم نظام «التقسيم العلمي»: المبحث والمطلب يميناً بذراعٍ واحدة تمتد إلى اليسار */
#book.hs-pro .h.hs-h2 .fs-a:first-child, #book.hs-pro .h.hs-h3 .fs-a:first-child { display: none; }

extras.script:
// التعقيبة: في ذيل كل صفحة يسرى (تُقلب بعدها الورقة) أولُ كلمة من الصفحة التالية، كما كان النسّاخ يصنعون
// (الصفحة اليسرى pg-l: هي الفردية في الكتاب العربي، والزوجية إن اختير أن تكون الفردية يمنى)
W.on('pageDone', function (p) {
  var el = p && p.el;
  if (!el || p.kind !== 'content' || !el.classList.contains('pg-l')) return;
  var nx = el.nextElementSibling;
  // (لا تعقيبة قبل صفحة تعليقٍ في المتون: ليس فيها نص)
  if (!nx || !nx.classList.contains('content') || nx.classList.contains('mcom')) return;
  var fl = nx.querySelector('.flow');
  if (!fl || !fl.firstElementChild) return;
  var c = fl.cloneNode(true);
  c.querySelectorAll('.fr, .rs, .srl-md, .vsep, .vno, .mc, .mc-label').forEach(function (x) { x.remove(); });
  var w = (c.textContent || '').trim().split(/\s+/)[0] || '';
  w = w.replace(/^[()\[\]«»﴿﴾"'“”.,:;،؛!؟ـ\-–—*]+|[()\[\]«»﴿﴾"'“”.,:;،؛!؟ـ\-–—*]+$/g, '');
  if (!w || w.length > 16 || /^[0-9٠-٩]+$/.test(w)) return;
  var t = document.createElement('div');
  t.className = 'tq';
  t.textContent = w;
  el.appendChild(t);
});

extras.css:
/* ============================ الزمرّدي ============================
   زمرّدٌ (لون الأبواب --c-h1) وذهبٌ (الخطوط --c-rule) وعقيقٌ (المتن --c-matn)،
   فما يختاره المستخدم من الألوان تتبعه الأشكال كلها. */
:root { --c-owner-ink: #B38B3F; }

/* ---------- ١) الإطار: ثلاثة خطوط بزوايا مستديرة، وشريطا سلسلة، ووردة في كل زاوية ----------
   كل شيء بحدود النص (--t-l --t-r): يتبع الهامش الواسع وهامش التجليد، وما يُكتب في الهامش خارجه */
.zf { position: absolute; top: calc(var(--m-top) - 13mm); bottom: calc(var(--m-bottom) - 8mm);
  left: calc(var(--t-l) - 5mm); right: calc(var(--t-r) - 5mm);
  border: .9pt solid var(--c-rule); border-radius: 3mm; }
.zf::before { content: ''; position: absolute; inset: .8mm; border: .35pt solid var(--c-rule); border-radius: 2.3mm; }
.zf::after { content: ''; position: absolute; inset: -1.1mm; border: .4pt solid var(--c-h1); border-radius: 4mm; }
.zband { position: absolute; height: 2.6mm; left: calc(var(--t-l) - 4mm); right: calc(var(--t-r) - 4mm);
  background: asset(band) center / 100% 100% no-repeat; }
.zband.t { top: calc(var(--m-top) - 19.4mm); }
.zband.b { bottom: calc(var(--m-bottom) - 14.4mm); }
.zc { position: absolute; width: 6.6mm; height: 6.6mm; background: asset(rose) center / 100% 100% no-repeat; }
.zc.tl, .zc.tr { top: calc(var(--m-top) - 16.3mm); }
.zc.bl, .zc.br { bottom: calc(var(--m-bottom) - 11.3mm); }
.zc.tl, .zc.bl { left: calc(var(--t-l) - 8.3mm); }
.zc.tr, .zc.br { right: calc(var(--t-r) - 8.3mm); }
/* الوردة في زاويةٍ يُكتب بجانبها في الهامش تُرفع (موضعٌ لا ارتفاع) */
.page:has(> .mside-n.l) .zc.tl, .page:has(> .mside-n.l) .zc.bl,
.page:has(> .mside-n.r) .zc.tr, .page:has(> .mside-n.r) .zc.br { display: none; }
#book.no-orn .zband, #book.no-orn .zc { display: none; }
/* ما يُكتب في الهامش خارج الإطار (بُعده ٥ مم + خطوطه + فسحة)، وفوق دارة الرقم والوردتين السفليين */
.page.content, .page.toc { --mside-clear: 7mm; --mside-bottom: 21mm; }

/* ---------- ٢) الترويسة داخل الإطار، بين معيّنين ---------- */
.rh { top: calc(var(--m-top) - 11.6mm); font-size: 10pt; color: var(--c-h1); border-bottom: 0; padding-bottom: 0; }
.rh > span::before, .rh > span::after { content: ''; display: inline-block; width: 1.25mm; height: 1.25mm; margin: 0 2.6mm;
  background: var(--c-matn); transform: rotate(45deg); vertical-align: .22em; }

/* ---------- ٣) رقم الصفحة في دارةٍ على خط الإطار السفلي ---------- */
.folio { bottom: calc(var(--m-bottom) - 13mm); font-size: 11pt; line-height: 1; }
.zfo { display: inline-flex; align-items: center; justify-content: center; min-width: 10mm; height: 10mm; padding: 0 1.6mm;
  border: .9pt solid var(--c-rule); border-radius: 5mm; background: var(--paper); color: var(--c-h1); font-family: var(--f-heading);
  box-shadow: inset 0 0 0 .55mm var(--paper), inset 0 0 0 .8mm var(--c-h1); }

/* ---------- ٤) الباب: وردةٌ فوق لوحٍ زمرّدي مشطوف الطرفين (كلوح عنوان الغلاف)، وخطّان يمتدان منه ---------- */
.h1 { margin: 0 0 6mm; padding-top: 5mm; line-height: 1.55; }
.h1::after { display: none; }
.zb { display: flex; flex-direction: column; align-items: center; }
.zb-rose { position: relative; z-index: 1; display: block; width: 9mm; height: 9mm; margin-bottom: -2.6mm; }
.zb-row { position: relative; width: 100%; display: flex; justify-content: center; }
.zb-row::before { content: ''; position: absolute; left: 0; right: 0; top: 50%; height: 1.6mm; margin-top: -.8mm;
  border-top: .5pt solid var(--c-rule); border-bottom: .5pt solid var(--c-rule); }
.zb-plate, .zb-in { clip-path: polygon(5mm 0, calc(100% - 5mm) 0, calc(100% - 5mm) 1.6mm, calc(100% - 2.4mm) 1.6mm, 100% 50%,
  calc(100% - 2.4mm) calc(100% - 1.6mm), calc(100% - 5mm) calc(100% - 1.6mm), calc(100% - 5mm) 100%, 5mm 100%,
  5mm calc(100% - 1.6mm), 2.4mm calc(100% - 1.6mm), 0 50%, 2.4mm 1.6mm, 5mm 1.6mm); }
.zb-plate { position: relative; min-width: 58%; max-width: 100%; padding: .7mm; background: var(--c-rule); }
.zb-in { position: relative; padding: 2.8mm 13mm 3.2mm; background: var(--c-h1); color: var(--paper); text-align: center; }
.zb-in::before { content: ''; position: absolute; top: 1.15mm; bottom: 1.15mm; left: 6.2mm; right: 6.2mm;
  border-top: .35pt solid var(--c-rule); border-bottom: .35pt solid var(--c-rule); }
.zb-t { position: relative; }

/* ---------- ٥) الفصل بين خطين مزدوجين ومعيّنين، والفرعي بوردة، والرابع بمعيّن ---------- */
.h2 { margin: 5.5mm 0 3.6mm; }
.z2 { display: flex; align-items: center; justify-content: center; gap: 2.4mm; }
.z2 > b { flex: 0 1 auto; font-weight: inherit; }
.z2 > .zl { flex: 1 1 0; min-width: 5mm; max-width: 24mm; height: 1.3mm; border-top: .5pt solid var(--c-rule); border-bottom: .5pt solid var(--c-rule); }
.z2 > .zd { flex: none; width: 1.6mm; height: 1.6mm; background: var(--c-h1); transform: rotate(45deg); }
.z3 { display: inline-block; width: .8em; height: .8em; vertical-align: -.07em; margin-inline-end: 1.8mm; }
.h4::before { content: ''; display: inline-block; width: 1.4mm; height: 1.4mm; margin-inline-end: 2mm; vertical-align: .24em;
  background: var(--c-h1); transform: rotate(45deg); }

/* ---------- ٦) الفاصل الزخرفي وخط «شرح:» ---------- */
.orn { line-height: 0; margin: 3mm 0 4mm; }
.orn .zo { display: inline-block; height: 5.6mm; width: auto; max-width: 85%; }
.shrule { border-top: 0; height: 2.6mm; margin: 2.2mm 0 2.6mm; background: asset(band) center / 100% 100% no-repeat; }
.shlabel.strong { color: var(--c-h1); }

/* ---------- ٧) المتن في كتب الشروح: خانةٌ بحدّين ذهبيين على ظلٍّ زمرّدي خفيف ---------- */
#book:not(.w-mutun):not(.tpl-matn) .p.mt { padding: 0 3.4mm; border-left: .7pt solid var(--c-rule); border-right: .7pt solid var(--c-rule);
  background: color-mix(in srgb, var(--c-h1) 4%, var(--paper)); }
#book:not(.w-mutun):not(.tpl-matn) .p.mt:not(.p.mt + .p.mt):not(.cont) { border-top: .7pt solid var(--c-rule); padding-top: 1.6mm; margin-top: 2.4mm; border-radius: 1.6mm 1.6mm 0 0; }
#book:not(.w-mutun):not(.tpl-matn) .p.mt:not(:has(+ .p.mt)):not(.brk) { border-bottom: .7pt solid var(--c-rule); padding-bottom: 1.6mm; margin-bottom: 2.4mm; border-radius: 0 0 1.6mm 1.6mm; }
#book:not(.w-mutun):not(.tpl-matn) .p.mt:not(.p.mt + .p.mt):not(.cont):not(:has(+ .p.mt)):not(.brk) { border-radius: 1.6mm; }

/* ---------- ٨) الحواشي: خطٌّ ذهبي ينتهي بمعيّن زمرّدي ---------- */
.fnsep { position: relative; width: 30%; border-top-color: var(--c-rule); }
.fnsep::after { content: ''; position: absolute; left: -.8mm; top: -.88mm; width: 1.3mm; height: 1.3mm; background: var(--c-h1); transform: rotate(45deg); }
.fn .fnn { color: var(--c-h1); }

/* ---------- ٩) الفهرس: رأسه على لوح الباب ---------- */
.zt { margin: 0 0 4mm; }
.zt .zb-t { font-family: 'Aref Ruqaa', var(--f-heading); font-weight: 700; font-size: var(--s-h1); line-height: 1.5; }
.toc-head { color: var(--c-h2); border-bottom: .5pt solid var(--c-rule); padding: 0 1mm 1mm; }
.toc-e .ld { color: var(--c-rule); }
.toc-e .n { color: var(--c-h1); }

/* ---------- ١٠) خانة الهامش: بقدر ما يُكتب فيها، ولا تظهر إلا حيث كُتب ----------
   إطاران (ذهبي وزمرّدي) على ظلٍّ خفيف، ووردةٌ على حافتها العليا، ولسانٌ ذهبي يشير إلى الفقرة من جهة النص */
#book .mside-n.framed { padding: 1.9mm 2.1mm 1.5mm; border: .5pt solid var(--c-rule); border-radius: 1.4mm;
  background: color-mix(in srgb, var(--c-h1) 5%, var(--paper));
  box-shadow: inset 0 0 0 .55mm var(--paper), inset 0 0 0 .75mm color-mix(in srgb, var(--c-h1) 60%, transparent); }
#book .mside-n.framed::before { content: ''; position: absolute; top: -1.6mm; left: 50%; width: 3.2mm; height: 3.2mm; margin-left: -1.6mm;
  background: asset(rose) center / 100% 100% no-repeat; }
#book .mside-n.framed::after { content: ''; position: absolute; top: 2.4mm; width: 1.6mm; height: 1.6mm; background: var(--c-rule); transform: rotate(45deg); }
#book .mside-n.framed.l::after { right: -.95mm; }
#book .mside-n.framed.r::after { left: -.95mm; }
/* (وبلا خانة: خطٌّ ذهبي يفصله عن النص، من إعداد الهامش نفسه) */

/* ---------- ١١) المتون ---------- */
/* «قبل المتن»: وردةٌ ثم النص على خطٍّ ذهبي */
.mintro > span { padding: 0 1.2mm .5mm; border-bottom: .6pt solid var(--c-rule); }
.mintro > span::before { content: ''; display: inline-block; width: .82em; height: .82em; margin: 0 0 0 1.6mm; vertical-align: -.1em;
  background: asset(rosette) center / 100% 100% no-repeat; }
/* عنوان التعليق في لوحٍ مسدّس (كخانات الكعب) */
.mc-label > span { padding: .3mm 8mm .7mm; background: color-mix(in srgb, var(--mlc) 8%, var(--paper));
  border-top: .6pt solid var(--c-rule); border-bottom: .6pt solid var(--c-rule);
  clip-path: polygon(3.4mm 0, calc(100% - 3.4mm) 0, 100% 50%, calc(100% - 3.4mm) 100%, 3.4mm 100%, 0 50%); }
/* التعليق تحت المتن: سلسلةٌ بدل الخط */
.msep { border-top: 0; height: 2.6mm; margin: 0 0 3mm; background: asset(band) center / 100% 100% no-repeat; }
/* صفحة التعليق المقابلة: موضع الكتابة في إطارين */
.page.mcom .mc { border: .6pt solid var(--c-rule); border-radius: 2.4mm; padding: 2.4mm 3.2mm 3mm;
  box-shadow: inset 0 0 0 .7mm var(--paper), inset 0 0 0 .9mm color-mix(in srgb, var(--c-h1) 45%, transparent); }
/* الهامش بجانب المتن: خطٌّ مزدوج ذهبي */
.mside-right .mc-side::after, .mside-left .mc-side::after { border-inline-start: 1.8pt double var(--c-rule); }
/* أرقام الأبيات */
.verse > .vno, .verse > .vsep.vmid { color: var(--c-h1); }
.verse > .vno { border-inline-end-color: color-mix(in srgb, var(--c-rule) 70%, transparent); }

/* ---------- ١٢) الغلاف الداخلي: إطاران، وشريطا سلسلة، ووردات الزوايا، والعنوان على لوحٍ في وسط الدارة ---------- */
.page.cover::before { content: ''; position: absolute; top: 7mm; bottom: 7mm; left: calc(7mm + var(--g-l)); right: calc(7mm + var(--g-r));
  border: 2.2pt solid var(--c-h1); pointer-events: none; }
.page.cover::after { content: ''; position: absolute; top: 9.3mm; bottom: 9.3mm; left: calc(9.3mm + var(--g-l)); right: calc(9.3mm + var(--g-r));
  border: .5pt solid var(--c-rule); pointer-events: none; }
.zv { position: absolute; inset: 0; }
.zv-band { position: absolute; left: 1.5mm; right: 1.5mm; height: 2.6mm; background: asset(band) center / 100% 100% no-repeat; }
.zv-band.t { top: -2.2mm; }
.zv-band.b { bottom: -2.2mm; }
.zv-c { position: absolute; width: 9mm; height: 9mm; background: asset(rose) center / 100% 100% no-repeat; }
.zv-c.tl, .zv-c.tr { top: -9.2mm; }
.zv-c.bl, .zv-c.br { bottom: -9.2mm; }
.zv-c.tl, .zv-c.bl { left: -9.2mm; }
.zv-c.tr, .zv-c.br { right: -9.2mm; }
.zv-in { position: absolute; top: 4mm; bottom: 4mm; left: 2mm; right: 2mm; display: flex; flex-direction: column; align-items: center;
  justify-content: space-between; text-align: center; }
.zv-top { min-height: 8mm; }
.zv-vol { display: inline-block; padding: .4mm 7mm; font-family: var(--f-heading); font-weight: 700; font-size: 14pt; color: var(--c-h1);
  border-top: .6pt solid var(--c-rule); border-bottom: .6pt solid var(--c-rule); }
.zv-med { flex: none; width: 100mm; height: 100mm; display: flex; align-items: center; justify-content: center;
  background: asset(medal) center / 100% 100% no-repeat; }
.zv-med .zb-plate { min-width: 84mm; max-width: 126mm; }
.zv-med .zb-in { padding: 4mm 14mm 4.6mm; }
.zv-title { position: relative; font-family: var(--f-cover); font-weight: 700; font-size: 30pt; line-height: 1.45; }
.zv-sub { position: relative; margin-top: 1mm; font-family: var(--f-heading); font-weight: 700; font-size: 14pt; line-height: 1.5;
  color: color-mix(in srgb, var(--c-rule) 55%, var(--paper)); }
.zv-names { display: flex; flex-direction: column; align-items: center; }
.zv-lbl { font-size: 12pt; color: var(--c-rule); line-height: 1.4; }
.zv-author { font-family: var(--f-names); font-weight: 700; font-size: 21pt; line-height: 1.6; color: var(--c-h1); }
.zv-note { font-size: 11.5pt; color: var(--c-text); }
.zv-ed { margin-top: 4mm; }
.zv-editor { font-family: var(--f-names); font-weight: 700; font-size: 16pt; line-height: 1.6; color: var(--c-h2); }
.zv-bottom { min-height: 6mm; font-size: 11.5pt; line-height: 1.6; color: var(--c-h2); }
/* خانات صاحب النسخة: في لوحٍ مؤطّر تعلوه وردة، والدارة تصغر لها */
.zv .cv-owner { position: relative; width: 80%; margin: 2mm auto 0; padding: 4mm 6mm 3.4mm; gap: 4.2mm 2.5mm; font-size: 12pt;
  color: var(--c-h1); border: .6pt solid var(--c-rule); border-radius: 2.4mm; background: color-mix(in srgb, var(--c-h1) 4%, var(--paper)); }
.zv .cv-owner::before { content: ''; position: absolute; top: -3mm; left: 50%; width: 6mm; height: 6mm; margin-left: -3mm;
  background: asset(rose) center / 100% 100% no-repeat; }
.page.cover.has-owner .zv-med { width: 82mm; height: 82mm; }
.page.cover.has-owner .zv-med .zb-plate { min-width: 76mm; }
.page.cover.has-owner .zv-title { font-size: 25pt; }
.page.cover.has-owner .zv-author { font-size: 19pt; }

/* ============================ البستان ============================
   عقيقٌ (لون الأبواب --c-h1) وذهبٌ (الخطوط --c-rule) وأخضرُ داكن (الفصول --c-h2)،
   فما يختاره المستخدم من الألوان تتبعه الأشكال كلها (والزخارف المرسومة بألوان الغلاف نفسه). */
:root { --c-owner-ink: #B39048;
  /* شكل الخرطوشة: لوحٌ بطرفين مقوّسين مدبّبين، وبروزٌ في وسط أعلاه وأسفله (كلوح الغلاف) */
  --kp: polygon(9mm 2mm, calc(50% - 5mm) 2mm, calc(50% - 2.2mm) 1.3mm, 50% 0, calc(50% + 2.2mm) 1.3mm, calc(50% + 5mm) 2mm,
    calc(100% - 9mm) 2mm, calc(100% - 6mm) 2.6mm, calc(100% - 4.2mm) 4mm, calc(100% - 3.4mm) calc(50% - 2.6mm), calc(100% - 1.8mm) calc(50% - 1.1mm), 100% 50%,
    calc(100% - 1.8mm) calc(50% + 1.1mm), calc(100% - 3.4mm) calc(50% + 2.6mm), calc(100% - 4.2mm) calc(100% - 4mm), calc(100% - 6mm) calc(100% - 2.6mm), calc(100% - 9mm) calc(100% - 2mm),
    calc(50% + 5mm) calc(100% - 2mm), calc(50% + 2.2mm) calc(100% - 1.3mm), 50% 100%, calc(50% - 2.2mm) calc(100% - 1.3mm), calc(50% - 5mm) calc(100% - 2mm),
    9mm calc(100% - 2mm), 6mm calc(100% - 2.6mm), 4.2mm calc(100% - 4mm), 3.4mm calc(50% + 2.6mm), 1.8mm calc(50% + 1.1mm), 0 50%,
    1.8mm calc(50% - 1.1mm), 3.4mm calc(50% - 2.6mm), 4.2mm 4mm, 6mm 2.6mm);
  /* لوحٌ صغير بطرفين مدبّبين (عنوان التعليق) */
  --sp: polygon(3.4mm 0, calc(100% - 3.4mm) 0, 100% 50%, calc(100% - 3.4mm) 100%, 3.4mm 100%, 0 50%); }

/* ---------- ١) الإطار: خطٌّ عقيقي، وشريط معيّنات، وخطٌّ ذهبي، وكوشةٌ في كل زاوية ----------
   حول النص بحدوده (--t-l --t-r): يتبع الهامش الواسع وهامش التجليد، وما يُكتب في الهامش خارجه */
.deco .tf { position: absolute; top: calc(var(--m-top) - 13mm); bottom: calc(var(--m-bottom) - 12mm);
  left: calc(var(--t-l) - 7mm); right: calc(var(--t-r) - 7mm); }
.tf { border: .5pt solid var(--c-h1); }
.tb { position: absolute; }
.tb.t, .tb.b { left: .9mm; right: .9mm; height: 2.4mm; background: asset(band) center / 100% 100% no-repeat; }
.tb.t { top: .9mm; } .tb.b { bottom: .9mm; }
.tb.l, .tb.r { top: 3.3mm; bottom: 3.3mm; width: 2.4mm; background: asset(bandv) center / 100% 100% no-repeat; }
.tb.l { left: .9mm; } .tb.r { right: .9mm; }
.ti { position: absolute; inset: 3.6mm; border: .5pt solid var(--c-rule); }
.tk { position: absolute; width: 7.5mm; height: 7.5mm; background: asset(kosha) center / 100% 100% no-repeat; }
.deco .tk.tl, .deco .tk.tr { top: calc(var(--m-top) - 9.4mm); }
.deco .tk.bl, .deco .tk.br { bottom: calc(var(--m-bottom) - 8.4mm); }
.deco .tk.tl, .deco .tk.bl { left: calc(var(--t-l) - 3.4mm); }
.deco .tk.tr, .deco .tk.br { right: calc(var(--t-r) - 3.4mm); }
.tk.tr { transform: scaleX(-1); } .tk.bl { transform: scaleY(-1); } .tk.br { transform: scale(-1, -1); }
#book.no-orn .tk { display: none; }
/* ما يُكتب في الهامش خارج الإطار (بُعده ٧ مم + سمكه)، وفوق لوح الرقم */
.page.content, .page.toc { --mside-clear: 8mm; --mside-bottom: 19mm; }

/* ---------- ٢) الترويسة داخل الإطار، بين ترنجتين صغيرتين ---------- */
.rh { top: calc(var(--m-top) - 8.6mm); font-size: 10pt; color: var(--c-h2); border-bottom: 0; padding-bottom: 0; }
.rh > span::before, .rh > span::after { content: ''; display: inline-block; width: 1.7mm; height: 2.7mm; margin: 0 2.4mm; vertical-align: -.1em;
  background: asset(bud) center / 100% 100% no-repeat; }

/* ---------- ٣) رقم الصفحة في لوحٍ مدبّب تحت الإطار ---------- */
.folio { bottom: calc(var(--m-bottom) - 21.5mm); font-size: 11pt; line-height: 1; }
.tfo { display: inline-flex; align-items: center; justify-content: center; min-width: 17mm; height: 8.5mm; padding: 0 4.5mm .3mm;
  background: asset(folio) center / 100% 100% no-repeat; color: var(--c-h1); font-family: var(--f-heading); }

/* ---------- ٤) الباب: خرطوشةٌ مقوّسة الأطراف (خطٌّ عقيقي وخطٌّ ذهبي)، تعلوها ترنجة، ويحفّها غصنان ---------- */
.h1 { margin: 0 0 6mm; padding-top: 4mm; line-height: 1.55; }
.h1::after { display: none; }
.tr1 { display: flex; flex-direction: column; align-items: center; }
.tr-bud { display: block; width: 6mm; height: 9.4mm; margin-bottom: -.3mm; }
.tr-row { display: flex; align-items: center; justify-content: center; gap: .6mm; width: 100%; }
.tr-sp { flex: none; width: 16mm; height: 6.4mm; }
.tr-sp.r, .t2s.r { transform: scaleX(-1); }
.k1, .k2, .k3, .k4 { clip-path: var(--kp); }
.k1 { flex: 0 1 auto; min-width: 46%; padding: .55mm; background: var(--c-h1); }
.k2 { padding: .5mm; background: var(--paper); }
.k3 { padding: .4mm; background: var(--c-rule); }
.k4 { padding: 3.6mm 12mm 3.8mm; background: var(--paper); text-align: center; }

/* ---------- ٥) الفصل بين غصنين، والفرعي بترنجة، والرابع بمعيّن ---------- */
.h2 { margin: 5.5mm 0 3.6mm; }
.t2 { display: flex; align-items: center; justify-content: center; gap: 2mm; }
.t2 > b { flex: 0 1 auto; font-weight: inherit; }
.t2s { flex: none; width: 11mm; height: 4.4mm; }
.t3 { display: inline-block; width: .62em; height: .98em; vertical-align: -.2em; margin-inline-end: 1.8mm; }
.h4::before { content: ''; display: inline-block; width: 1.4mm; height: 1.4mm; margin-inline-end: 2mm; vertical-align: .24em;
  background: var(--c-h1); transform: rotate(45deg); }

/* ---------- ٦) الفاصل الزخرفي، وخط «شرح:»، وخط الحواشي: شريط المعيّنات ---------- */
.orn { line-height: 0; margin: 3mm 0 4mm; }
.orn .to { display: inline-block; height: 6mm; width: auto; max-width: 90%; }
.shrule { border-top: 0; height: 2.2mm; margin: 2.2mm 0 2.6mm; background: asset(band) center / 100% 100% no-repeat; }
.shlabel.strong { color: var(--c-h1); }
.fnsep { border-top: 0; width: 32%; height: 1.8mm; background: asset(band) center / 100% 100% no-repeat; }
.fn .fnn { color: var(--c-h1); }

/* ---------- ٧) المتن في كتب الشروح: خانةٌ بحدّين عقيقيين مزدوجين على ظلٍّ ذهبي خفيف ---------- */
#book:not(.w-mutun):not(.tpl-matn) .p.mt { padding: 0 3.6mm; border-left: 2pt double var(--c-h1); border-right: 2pt double var(--c-h1);
  background: color-mix(in srgb, var(--c-rule) 9%, var(--paper)); }
#book:not(.w-mutun):not(.tpl-matn) .p.mt:not(.p.mt + .p.mt):not(.cont) { border-top: .6pt solid var(--c-rule); padding-top: 1.6mm; margin-top: 2.4mm; }
#book:not(.w-mutun):not(.tpl-matn) .p.mt:not(:has(+ .p.mt)):not(.brk) { border-bottom: .6pt solid var(--c-rule); padding-bottom: 1.6mm; margin-bottom: 2.4mm; }

/* ---------- ٨) الفهرس: رأسه في خرطوشة الباب ---------- */
.tt { margin: 0 0 4mm; }
.tt .k4 { font-family: 'Aref Ruqaa', var(--f-heading); font-weight: 700; font-size: var(--s-h1); line-height: 1.5; color: var(--c-h1); }
.toc-head { color: var(--c-h2); border-bottom: .5pt solid var(--c-rule); padding: 0 1mm 1mm; }
.toc-e .ld { color: var(--c-rule); }
.toc-e .n { color: var(--c-h1); }

/* ---------- ٩) خانة الهامش: بقدر ما يُكتب فيها، ولا تظهر إلا حيث كُتب ----------
   خطٌّ عقيقي وخطٌّ ذهبي على ظلٍّ ذهبي خفيف، وترنجةٌ معلّقة بأعلاها، ولسانٌ عقيقي يشير إلى الفقرة من جهة النص */
#book .mside-n.framed { padding: 2.2mm 2.2mm 1.6mm; border: .5pt solid var(--c-h1); border-radius: .5mm;
  background: color-mix(in srgb, var(--c-rule) 9%, var(--paper));
  box-shadow: inset 0 0 0 .5mm var(--paper), inset 0 0 0 .72mm var(--c-rule); }
#book .mside-n.framed::before { content: ''; position: absolute; top: -1.9mm; left: 50%; width: 2.3mm; height: 3.6mm; margin-left: -1.15mm;
  background: asset(bud) center / 100% 100% no-repeat; }
#book .mside-n.framed::after { content: ''; position: absolute; top: 2.4mm; width: 1.5mm; height: 1.5mm; background: var(--c-h1); transform: rotate(45deg); }
#book .mside-n.framed.l::after { right: -.9mm; }
#book .mside-n.framed.r::after { left: -.9mm; }
/* (وبلا خانة: خطٌّ يفصله عن النص، من إعداد الهامش نفسه) */

/* ---------- ١٠) المتون ---------- */
/* «قبل المتن»: ترنجةٌ ثم النص على خطٍّ ذهبي */
.mintro > span { padding: 0 1.2mm .5mm; border-bottom: .6pt solid var(--c-rule); }
.mintro > span::before { content: ''; display: inline-block; width: .6em; height: .95em; margin: 0 0 0 1.8mm; vertical-align: -.18em;
  background: asset(bud) center / 100% 100% no-repeat; }
/* عنوان التعليق في لوحٍ مدبّب الطرفين */
.mc-label > span { padding: .3mm 8mm .7mm; background: color-mix(in srgb, var(--c-rule) 14%, var(--paper));
  border-top: .6pt solid var(--mlc); border-bottom: .6pt solid var(--mlc); clip-path: var(--sp); }
/* التعليق تحت المتن: شريط المعيّنات بدل الخط */
.msep { border-top: 0; height: 2.4mm; margin: 0 0 3mm; background: asset(band) center / 100% 100% no-repeat; }
/* صفحة التعليق المقابلة: موضع الكتابة في خطٍّ عقيقي وخطٍّ ذهبي */
.page.mcom .mc { border: .6pt solid var(--c-h1); padding: 2.4mm 3.2mm 3mm;
  box-shadow: inset 0 0 0 .7mm var(--paper), inset 0 0 0 .95mm var(--c-rule); }
/* الهامش بجانب المتن: شريط المعيّنات قائماً */
.mside-right .mc-side::after, .mside-left .mc-side::after { border: 0; width: 2.4mm; background: asset(bandv) center / 100% 100% no-repeat; }
.mside-right .mc-side::after { right: -3.7mm; }
.mside-left .mc-side::after { left: -3.7mm; }
/* أرقام الأبيات */
.verse > .vno, .verse > .vsep.vmid { color: var(--c-h1); }
.verse > .vno { border-inline-end-color: color-mix(in srgb, var(--c-rule) 70%, transparent); }

/* ---------- ١١) الغلاف الداخلي: الإطار نفسه، وكوشاتٌ كبيرة، والعنوان في خرطوشةٍ تعلوها ترنجة وتحتها أخرى ---------- */
.tv { position: absolute; inset: 0; }
.tv .tf { position: absolute; top: -7mm; bottom: -7mm; left: -7mm; right: -7mm; }
.tv .tk { width: 24mm; height: 24mm; }
.tv .tk.tl, .tv .tk.tr { top: -3.4mm; }
.tv .tk.bl, .tv .tk.br { bottom: -3.4mm; }
.tv .tk.tl, .tv .tk.bl { left: -3.4mm; }
.tv .tk.tr, .tv .tk.br { right: -3.4mm; }
.tv-in { position: absolute; top: 3mm; bottom: 3mm; left: 2mm; right: 2mm; display: flex; flex-direction: column; align-items: center;
  justify-content: space-between; text-align: center; }
.tv-top { min-height: 9mm; }
.tv-vol { display: inline-block; padding: 1.6mm 11mm 1.9mm; font-family: var(--f-heading); font-weight: 700; font-size: 14pt; line-height: 1.4;
  color: var(--c-h2); background: asset(folio) center / 100% 100% no-repeat; }
.tv-cart { flex: none; width: 140mm; height: 93.3mm; display: flex; align-items: center; justify-content: center;
  background: asset(cartouche) center / 100% 100% no-repeat; }
.tv-tt { max-width: 92mm; }
.tv-title { font-family: var(--f-cover); font-weight: 700; font-size: 30pt; line-height: 1.4; color: var(--c-h1); }
.tv-sub { margin-top: 1mm; font-family: var(--f-heading); font-weight: 700; font-size: 14pt; line-height: 1.5; color: var(--c-h2); }
.tv-names { display: flex; flex-direction: column; align-items: center; }
.tv-lbl { font-size: 12pt; color: var(--c-rule); line-height: 1.4; }
.tv-author { font-family: var(--f-names); font-weight: 700; font-size: 21pt; line-height: 1.6; color: var(--c-h2); }
.tv-note { font-size: 11.5pt; color: var(--c-text); }
.tv-ed { margin-top: 4mm; }
.tv-editor { font-family: var(--f-names); font-weight: 700; font-size: 16pt; line-height: 1.6; color: var(--c-h1); }
.tv-bottom { min-height: 6mm; font-size: 11.5pt; line-height: 1.6; color: var(--c-h2); }
/* خانات صاحب النسخة: في لوحٍ بخطٍّ عقيقي وذهبي تعلوه ترنجة؛ والخرطوشة والكوشات تصغر لها */
.tv .cv-owner { position: relative; width: 70%; margin: 3mm auto 0; padding: 4.4mm 6mm 3.4mm; gap: 4.2mm 2.5mm; font-size: 12pt;
  color: var(--c-h2); border: .6pt solid var(--c-h1); background: color-mix(in srgb, var(--c-rule) 8%, var(--paper));
  box-shadow: inset 0 0 0 .6mm var(--paper), inset 0 0 0 .82mm var(--c-rule); }
.tv .cv-owner::before { content: ''; position: absolute; top: -3.2mm; left: 50%; width: 4mm; height: 6.4mm; margin-left: -2mm;
  background: asset(bud) center / 100% 100% no-repeat; }
.page.cover.has-owner .tv-cart { width: 120mm; height: 80mm; }
.page.cover.has-owner .tv-tt { max-width: 78mm; }
.page.cover.has-owner .tv-title { font-size: 25pt; }
.page.cover.has-owner .tv .tk { width: 18mm; height: 18mm; }
.page.cover.has-owner .tv-author { font-size: 19pt; }

/* ====== حِبر — أسلوب الكتب القديمة السادة ======
   أسودٌ خالص على الورق: لا زخارف ولا صور ولا إطارات صفحات ولا خطوط زينة ولا ألوان.
   كل ألوانه سوداء وخطُّه أميريّاً واحداً، وبنظام التقسيم العلمي (pro) فالعناوين
   كما رسمها البرنامج: الباب في صفحةٍ فرديةٍ وحده، والفصل بعده، بلا خطٍّ تحتها.
   هذا الملف لا يضيف شكلاً، وإنما ينفي زينات الافتراض ويُسوِّد ما رسمه البرنامج
   بلونٍ آخر: الخط تحت عنوان الباب، والخط تحت عنوان الفهرس، وخطُّ الترويسة،
   وسطرُ الزخرفة في الغلاف، وحبرُ الترويسة والفرعي والمؤلف والتحقيق والملاحظة
   ودار النشر ورأس الفهرس وخانات الاسم والرقم. وما سوى ذلك من البرنامج نفسه. */

/* لا خطَّ تحت عنوان الباب */
#book .h1::after { display: none; }
/* ولا خطَّ تحت عنوان الفهرس */
#book .toc-rule { display: none; }
/* ولا خطَّ تحت الترويسة (اسم الكتاب والباب نصٌّ سادٌّ لا أكثر) */
#book .rh { color: #000000; border-bottom: 0; }
/* ولا سطرَ زخرفةٍ في الغلاف (وإن جاء من إعدادٍ ما): يعوَّض بسطرٍ من الفراغ */
#book .cv-orn { display: none; }
#book .cv-title { margin-bottom: 8mm; }

/* — حبرٌ أسود في كل ما يرسمه البرنامج بلونٍ آخر افتراضياً: الأسلوب بلونٍ واحدٍ هو الأسود — */
#book { --c-owner-ink: #000000; }
#book .cv-sub, #book .cv-author, #book .cv-note, #book .cv-editor, #book .cv-bottom { color: #000000; }
#book .toc-head { color: #000000; }
#book .ht-sub, #book .ht-author { color: #000000; }

/* ═══════════ نجد — من عمارة نجد ونقوشها ═══════════ */
:root { --ink: #231B15; --mudd: #7A5536; --mud: #B28659; --mudl: #DCC29C; --gyp: #F7F1E6; --wood: #6B4428; --red: #A23B26; --green: #4C6B3C; --ochre: #CF9D3E; --blue: #3A5F80;
  /* الجصّ على لون الورق (أبيض أو أصفر) */
  --gypp: color-mix(in srgb, var(--gyp) 70%, var(--paper)); --c-owner-ink: #7A5536; }

/* ١) الجدار: إطارٌ بخطين حول النص (بحدوده: يتبع الهامش الواسع وهامش التجليد)، تعلوه الشُّرَف، وتحته شريط المثلثات المقلوبة */
.jw { position: absolute; top: calc(var(--m-top) - 9mm); bottom: calc(var(--m-bottom) - 8mm); left: calc(var(--t-l) - 7mm); right: calc(var(--t-r) - 7mm); border: .9pt solid var(--mudd); }
.jw::after { content: ''; position: absolute; inset: .8mm; border: .3pt solid var(--mudd); }
.srf { position: absolute; top: calc(var(--m-top) - 14.4mm); height: 5.6mm; left: calc(var(--t-l) - 7mm); right: calc(var(--t-r) - 7mm);
  background: asset(parl) left bottom / 50% 100% no-repeat, asset(parr) right bottom / 50% 100% no-repeat; }
/* في وسط الشُّرَف لوحة جصّية صغيرة بدوّار الشمس (تغطيها لوحة الترويسة حيث تكون) */
.srf::after { content: ''; position: absolute; left: 50%; bottom: 0; width: 15mm; height: 6.4mm; margin-left: -7.5mm; background: asset(sund) center / 4.8mm 4.8mm no-repeat, var(--gyp); border: .6pt solid var(--mudd); box-shadow: 0 0 0 .5mm var(--paper), inset 0 0 0 .5mm var(--gyp), inset 0 0 0 .75mm var(--mud); }
.vb { position: absolute; top: calc(var(--m-top) - 7.9mm); height: 2.3mm; left: calc(var(--t-l) - 6mm); right: calc(var(--t-r) - 6mm); background: asset(vband) center top / 100% 100% no-repeat; }
/* المِرزاب: مسيل خشبي يبرز من الجدار في الطرف الخارجي — ويُرفع حيث يُكتب في ذلك الهامش، وفي الهامش الواسع */
.mzr { position: absolute; top: calc(var(--m-top) - 7.9mm); width: 10mm; height: 3.8mm; background: asset(spout) center / 100% 100% no-repeat; }
.page.pg-l .mzr { left: calc(var(--t-l) - 16.6mm); transform: scaleX(-1); }
.page.pg-r .mzr { right: calc(var(--t-r) - 16.6mm); }
#book.om-wide .mzr, .page.pg-l:has(> .mside-n.l) .mzr, .page.pg-r:has(> .mside-n.r) .mzr { display: none; }
/* ما يُكتب في الهامش خارج الجدار (بُعده ٧ مم + خطّاه + فسحة) */
.page.content, .page.toc { --mside-clear: 8.5mm; --mside-bottom: 12mm; --mside-edge: 1.2mm; }
#book.om-wide .page.content, #book.om-wide .page.toc { --mside-edge: 5mm; }

/* ٢) الترويسة: لوحة جصّية بين الشُّرَف (فوق النص بحدوده) */
.rh { top: calc(var(--m-top) - 14.9mm); left: var(--t-l); right: var(--t-r); height: 6.6mm; padding: 0; border: 0; overflow: visible; line-height: 1; text-align: center; }
.rp { display: inline-flex; align-items: center; height: 6.6mm; max-width: 92mm; padding: 0 5mm; background: var(--gyp); border: .6pt solid var(--mudd); box-shadow: 0 0 0 .5mm var(--paper), inset 0 0 0 .5mm var(--gyp), inset 0 0 0 .75mm var(--mud); }
.rp b { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: var(--f-heading); font-weight: 700; font-size: 9.5pt; line-height: 1.6; color: var(--mudd); }

/* ٣) رقم الصفحة في «دوّار الشمس» على أساس الجدار */
.folio { bottom: calc(var(--m-bottom) - 13.1mm); left: var(--t-l); right: var(--t-r); height: 10.2mm; line-height: 1; }
.fo { display: inline-flex; align-items: center; justify-content: center; width: 10.2mm; height: 10.2mm; background: asset(sun) center / 100% 100% no-repeat; }
.fo b { display: inline-flex; align-items: center; justify-content: center; min-width: 4.6mm; height: 4.6mm; padding: .3mm .5mm 0; border-radius: 2.3mm; background: #F4EEE2; font-family: var(--f-heading); font-weight: 700; font-size: 8pt; color: var(--ink); }

/* ٤) رأس الباب: عارضةٌ من خشب الأثل — تيجان، مسامير «أبو طبعة»، قيطان، دوّار الشمس برقم الباب، ولوح منقوش فيه اسمه */
.h1 { margin: 0 0 7mm; padding-top: 1mm; line-height: 1.5; }
.h1::after { display: none; }
.nb-cr { display: block; height: 4.2mm; margin: 0 5mm -.2mm; background: asset(crowns) center bottom / 100% 100% no-repeat; }
.nb-p { position: relative; padding: 2.5mm 2.4mm; border: .5pt solid var(--ink); background: linear-gradient(90deg, #6A4327, #8C5E38 30%, #7A5232 55%, #8F6039 80%, #684226); }
.nb-st { position: absolute; left: 2mm; right: 2mm; height: 2.2mm; background: asset(studs) center / 100% 100% no-repeat; }
.nb-st.st1 { top: .15mm; } .nb-st.st2 { bottom: .15mm; }
.nb-in { position: relative; display: flex; align-items: center; gap: 3mm; padding: 3mm 3.2mm;
  background-image: asset(braidh), asset(braidh), asset(braidv), asset(braidv);
  background-position: center top, center bottom, left center, right center;
  background-size: 100% 2mm, 100% 2mm, 2mm 100%, 2mm 100%; background-repeat: no-repeat; }
.nb-sun { flex: none; position: relative; width: 19mm; height: 19mm; display: flex; align-items: center; justify-content: center; background: asset(sun) center / 100% 100% no-repeat; font-style: normal; }
.nb-sun.sd { background-image: asset(sund); }
.nb-sun b { font-family: var(--f-heading); font-weight: 700; font-size: 12pt; line-height: 1; color: var(--ink); padding-top: .8mm; }
.nb-c { flex: 1 1 auto; min-width: 0; display: flex; align-items: center; justify-content: center; min-height: 19mm; padding: 4mm 4mm 3.6mm; text-align: center; border: .4pt solid var(--ink);
  background: asset(teeth) center top / 100% 2.4mm no-repeat, asset(drops) center bottom / 100% 2.4mm no-repeat, var(--gyp); }
.nb-t { font-family: 'Reem Kufi', var(--f-heading); font-weight: 700; color: var(--c-h1); }
/* الهامش الواسع (النص أضيق): الدوّاران أصغر · الهامش بجانب المتن: دوّارٌ واحد صغير، ليبقى لاسم الباب عرضه */
#book.om-wide .nb-sun { width: 14mm; height: 14mm; }
#book.om-wide .nb-sun b { font-size: 10.5pt; }
#book.om-wide .nb-c { min-height: 14mm; }
#book.mu-side .nb-sun { width: 12mm; height: 12mm; }
#book.mu-side .nb-sun b { font-size: 9.5pt; }
#book.mu-side .nb-sun.sd { display: none; }
#book.mu-side .nb-in { gap: 2mm; }
#book.mu-side .nb-c { min-height: 12mm; }

/* ٥) الفصل بين شريطين من السدو */
.h2 { margin: 6mm 0 4mm; }
.n2 { display: flex; align-items: center; gap: 3mm; }
.n2-s { flex: 1 1 0; min-width: 6mm; max-width: 30mm; height: 5mm; background: asset(sadu) center / 100% 100% no-repeat; border-radius: .4mm; }
.n2-t { flex: 0 1 auto; max-width: 78%; }

/* ٦) الفرعي بفتحة مثلثة (لَهْج)، والرابع بعين السدو */
.h3 { margin: 4.5mm 0 2.4mm; }
.n3 { display: inline-block; width: 4.2mm; height: 3.4mm; margin-inline-end: 1.8mm; vertical-align: -.1mm; background: asset(tri) center / contain no-repeat; }
.n4 { display: inline-block; width: 1.9mm; height: 1.9mm; margin-inline-end: 2.2mm; vertical-align: .55mm; background: var(--red); box-shadow: 0 0 0 .45mm #F4EEE2, 0 0 0 .7mm var(--ink); transform: rotate(45deg); }

/* ٧) الفاصل صفّ من اللهوج، وبين الشطرين دوّار شمس صغير، وفوق الحواشي شُرَف صغيرة */
.orn { margin: 3mm 0 4mm; line-height: 0; }
.ornt { display: block; height: 6.6mm; background: asset(furjat) center / contain no-repeat; }
.verse > .vsep, .fnv > .vsep { color: transparent; min-width: 4.4mm; background: asset(sun) center / 3.6mm 3.6mm no-repeat; }
.verse > .vsep.vmid { color: var(--red); background: none; }
.fnsep { width: 34mm; height: 3.2mm; border-top: 0; margin: 0 0 1.3mm; background: asset(fnsep) right bottom / 34mm 3.2mm no-repeat; }
.notes.sh .fnsep { width: 100%; background: asset(fnsep) right bottom / 34mm 3.2mm no-repeat, linear-gradient(var(--mud), var(--mud)) left bottom / calc(100% - 33mm) .5mm no-repeat; }
.fn .fnn, .fr { color: var(--red); }

/* ٨) الفهرس: لوحة جصّية ولهوج */
.nt { padding-top: 1mm; }
.nt-p { padding: 2.4mm 4mm 1.6mm; background: var(--gyp); border: .7pt solid var(--mudd); box-shadow: inset 0 0 0 .6mm var(--gyp), inset 0 0 0 .85mm var(--mud); text-align: center; font-family: 'Reem Kufi', var(--f-heading); font-weight: 700; font-size: 20pt; line-height: 1.5; color: var(--c-h1); }
.nt-f { display: block; height: 6mm; margin: 2mm auto 0; width: 46mm; background: asset(furjat) center / contain no-repeat; }
.tch .toc-head { margin: 3mm 0 2mm; padding-bottom: 1mm; border-bottom: .5pt solid var(--mudd); font-family: var(--f-heading); font-size: 11pt; color: var(--red); }
.toc-e .ld { color: var(--mud); }
.toc-e.l1 { margin-top: 2mm; }
.toc-e.l1 .t::before { content: ''; display: inline-block; width: 3.2mm; height: 3.2mm; margin-inline-end: 1.6mm; vertical-align: -.25mm; background: asset(sun) center / contain no-repeat; }
.toc-e.l2 .t::before { content: ''; display: inline-block; width: 2.6mm; height: 2.1mm; margin-inline-end: 1.6mm; vertical-align: .1mm; background: asset(tri) center / contain no-repeat; }

/* ٩) الغلاف الداخلي: إطارٌ بخطين كجدار الصفحات، بين شريطي سدو، ولوحةٌ جصّية فيها العنوان، ودوّار الشمس، ثم الأسماء */
.page.cover .body { top: 0; bottom: 0; left: 0; right: 0; }
.fc { position: absolute; inset: 0; }
.fc-fr { position: absolute; top: 10mm; bottom: 10mm; left: calc(10mm + var(--g-l)); right: calc(10mm + var(--g-r)); border: .9pt solid var(--mudd); }
.fc-fr::after { content: ''; position: absolute; inset: .8mm; border: .3pt solid var(--mudd); }
.fc-sd { position: absolute; left: calc(14mm + var(--g-l)); right: calc(14mm + var(--g-r)); height: 5mm; background: asset(sadu) center / 100% 100% no-repeat; }
.fc-sd.t { top: 14mm; } .fc-sd.b { bottom: 14mm; }
.fc-cn { position: absolute; width: 8mm; height: 8mm; background: asset(sun) center / 100% 100% no-repeat; }
.fc-cn.tl, .fc-cn.tr { top: 6mm; } .fc-cn.bl, .fc-cn.br { bottom: 6mm; }
.fc-cn.tl, .fc-cn.bl { left: calc(6mm + var(--g-l)); } .fc-cn.tr, .fc-cn.br { right: calc(6mm + var(--g-r)); }
.fc-in { position: absolute; top: 30mm; bottom: 26mm; left: calc(22mm + var(--g-l)); right: calc(22mm + var(--g-r)); display: flex; flex-direction: column; align-items: center; justify-content: space-between; text-align: center; }
.fc-pl { position: relative; width: 100%; padding: 9mm 7mm 8mm; background: var(--gypp); border: .8pt solid var(--mudd); box-shadow: inset 0 0 0 .8mm var(--gypp), inset 0 0 0 1.1mm var(--mud); }
.fc-pl::before, .fc-pl::after { content: ''; position: absolute; left: 2mm; right: 2mm; height: 4mm; background: asset(vbandl) center / 100% 100% no-repeat; }
.fc-pl::before { top: 1.6mm; } .fc-pl::after { bottom: 1.6mm; transform: scaleY(-1); }
.fc-vol { font-family: var(--f-heading); font-weight: 700; font-size: 11pt; line-height: 1.6; color: var(--red); margin-bottom: 1.5mm; }
.fc-title { font-family: var(--f-cover); font-weight: 700; font-size: 27pt; line-height: 1.5; color: #3B2A1E; }
.fc-sub { font-family: var(--f-heading); font-weight: 700; font-size: 13pt; line-height: 1.6; color: var(--red); margin-top: 1.5mm; }
.fc-sun { flex: none; width: 15mm; height: 15mm; background: asset(sun) center / 100% 100% no-repeat; }
.fc-nm { display: flex; flex-direction: column; align-items: center; }
.fc-lbl { display: flex; align-items: center; gap: 2.4mm; font-family: var(--f-heading); font-weight: 700; font-size: 10pt; line-height: 1.6; color: var(--mudd); }
.fc-lbl::before, .fc-lbl::after { content: ''; width: 3.4mm; height: 2.8mm; background: asset(tri) center / contain no-repeat; }
.fc-ed-l { margin-top: 3.5mm; }
.fc-au { font-family: var(--f-names); font-weight: 700; font-size: 18pt; line-height: 1.55; color: #3B2A1E; }
.fc-note { font-size: 10.5pt; line-height: 1.5; color: #6a5340; }
.fc-ed { font-family: var(--f-names); font-weight: 700; font-size: 14pt; line-height: 1.55; color: var(--red); }
.fc-bot { display: flex; flex-direction: column; align-items: center; font-family: var(--f-heading); font-size: 10.5pt; line-height: 1.7; color: #4a3626; }
.fc-bot::before { content: ''; display: block; width: 46mm; height: 5.6mm; margin-bottom: 1.5mm; background: asset(furjat) center / contain no-repeat; }
.fc-pub { font-weight: 700; color: #3B2A1E; }
/* خانات صاحب النسخة: لوحٌ جصّي بشريط المثلثات، والغلاف يتقارب لها */
.fc .cv-owner { width: 84%; margin: 0 auto; padding: 5.4mm 6mm 3.6mm; gap: 4.4mm 2.5mm; font-family: var(--f-heading); font-size: 12pt; color: var(--red);
  border: .7pt solid var(--mudd); box-shadow: inset 0 0 0 .6mm var(--gypp), inset 0 0 0 .85mm var(--mud);
  background: asset(vband) center top 1.2mm / calc(100% - 2.4mm) 2.3mm no-repeat, var(--gypp); }
.page.cover.has-owner .fc-in { top: 27mm; bottom: 23mm; }
.page.cover.has-owner .fc-pl { padding: 7.5mm 6mm 6.5mm; }
.page.cover.has-owner .fc-title { font-size: 24pt; }
.page.cover.has-owner .fc-sun { width: 11mm; height: 11mm; }
.page.cover.has-owner .fc-ed-l { margin-top: 2mm; }

/* صفحة العنوان المختصر في النسخة الجاهزة للطباعة */
.page.front-half .ht-box::after { content: ''; display: block; width: 46mm; height: 6mm; margin: 4mm auto 0; background: asset(furjat) center / contain no-repeat; }

/* ١٠) البسملة: لوحٌ جصّي مربّع مؤطّر بالقيطان، يعلوها دوّار الشمس، وتحتها صفّ اللهوج */
.bs { position: absolute; inset: 0; --bw: calc(var(--page-w) * .68); }
.bs-f { position: absolute; left: calc(50% - var(--bw) / 2 + (var(--g-l) - var(--g-r)) / 2); top: calc(46% - var(--bw) / 2); width: var(--bw); height: var(--bw);
  border: .9pt solid var(--mudd); background: var(--gypp); }
.bs-f::after { content: ''; position: absolute; inset: .8mm; border: .3pt solid var(--mudd); }
.bs-b { position: absolute; inset: 2.6mm;
  background-image: asset(braidh), asset(braidh), asset(braidv), asset(braidv);
  background-position: center top, center bottom, left center, right center;
  background-size: 100% 2mm, 100% 2mm, 2mm 100%, 2mm 100%; background-repeat: no-repeat; }
.bs-c { position: absolute; inset: 6.4mm; border: .4pt solid var(--mud); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6mm;
  background: asset(teeth) center top / 100% 2.4mm no-repeat, asset(drops) center bottom / 100% 2.4mm no-repeat; }
.bs-sun { width: 16mm; height: 16mm; background: asset(sun) center / 100% 100% no-repeat; }
.bs-t { font-family: 'Scheherazade New', var(--f-heading); font-size: calc(var(--bw) * .17); line-height: 1; color: #3B2A1E; }
.bs-fj { width: 50%; height: 6mm; background: asset(furjat) center / contain no-repeat; }

/* ١١) الختام: حرد المتن على هيئة المثلث المقلوب، يعلوه دوّار الشمس، وتحته صفّ اللهوج واسم الكتاب */
.kx { position: absolute; inset: 0; }
.kx-in { position: absolute; top: 27%; left: calc(22mm + var(--g-l)); right: calc(22mm + var(--g-r)); display: flex; flex-direction: column; align-items: center; text-align: center; }
.kx-sun { display: block; width: 15mm; height: 15mm; margin-bottom: 5mm; background: asset(sun) center / 100% 100% no-repeat; }
.kx-l { font-family: var(--f-heading); font-size: calc(var(--page-w) * .031); line-height: 2; color: var(--ink); white-space: nowrap; }
.kx-l.k1 { font-family: 'Reem Kufi', var(--f-heading); font-weight: 700; color: var(--red); font-size: calc(var(--page-w) * .036); line-height: 1.8; }
.kx-l.k6 { font-weight: 700; color: var(--red); }
.kx-tr { display: block; width: 5mm; height: 4.1mm; margin-top: 2.5mm; background: asset(tri) center / contain no-repeat; transform: scaleY(-1); }
.kx-f { display: block; width: 46mm; height: 6mm; margin: 6mm 0 2.5mm; background: asset(furjat) center / contain no-repeat; }
.kx-b { font-family: var(--f-heading); font-weight: 700; font-size: 11pt; line-height: 1.6; color: var(--mudd); }

/* ١٢) خانة الهامش: لوحٌ جصّي بقدر ما يُكتب فيه — خطّان طينيان، وشريط المثلثات في أعلاه، ولسانٌ أحمر يشير إلى الفقرة من جهة النص.
   تكبر بكبر ما كُتب، ولا تظهر إلا حيث كُتب (sideNote.box) */
#book .mside-n.framed { padding: 3.6mm 1.5mm 1.7mm; border: .6pt solid var(--mudd); border-radius: 0;
  background: asset(vband) center top 1.05mm / calc(100% - 2.1mm) 1.7mm no-repeat, var(--gypp);
  box-shadow: inset 0 0 0 .45mm var(--gypp), inset 0 0 0 .65mm var(--mud); }
#book .mside-n.framed::after { content: ''; position: absolute; top: 3.2mm; width: 1.5mm; height: 1.5mm; background: var(--red); transform: rotate(45deg); }
#book .mside-n.framed.l::after { right: -.95mm; }
#book .mside-n.framed.r::after { left: -.95mm; }
/* (وبلا خانة: خطٌّ طيني يفصله عن النص، من إعداد الهامش نفسه) */

/* ١٣) المتون */
/* «قبل المتن»: في لوحةٍ جصّية صغيرة، يسبقه لَهْجٌ مثلّث */
.mintro > span { display: inline-block; padding: .3mm 4.2mm .6mm; background: var(--gypp); border: .6pt solid var(--mudd);
  box-shadow: inset 0 0 0 .5mm var(--gypp), inset 0 0 0 .75mm var(--mud); }
.mintro > span::before { content: ''; display: inline-block; width: .72em; height: .6em; margin: 0 0 0 1.8mm; vertical-align: .02em; background: asset(tri) center / contain no-repeat; }
/* عنوان التعليق بين شريطين من السدو */
.mc-label > span::before, .mc-label > span::after { content: ''; display: inline-block; width: 9mm; height: 3.4mm; margin: 0 2.6mm; vertical-align: .12em;
  background: asset(sadu) center / 100% 100% no-repeat; border-radius: .3mm; }
/* التعليق تحت المتن: شريط المثلثات بدل الخط */
.msep { border-top: 0; height: 2.3mm; margin: 0 0 3mm; background: asset(vband) center / 100% 100% no-repeat; }
/* صفحة التعليق المقابلة: موضع الكتابة جدارٌ بخطين، وفي أعلاه شريط المثلثات */
.page.mcom .mc { border: .9pt solid var(--mudd); padding: 5mm 3.4mm 3mm;
  background: asset(vband) center top 1.6mm / calc(100% - 3.2mm) 2.3mm no-repeat;
  box-shadow: inset 0 0 0 .8mm var(--paper), inset 0 0 0 1.1mm var(--mudd); }
/* الهامش بجانب المتن: شريط القيطان قائماً */
.mside-right .mc-side::after, .mside-left .mc-side::after { border: 0; width: 2mm; background: asset(braidv) center / 100% 100% no-repeat; }
.mside-right .mc-side::after { right: -3.5mm; }
.mside-left .mc-side::after { left: -3.5mm; }
/* أرقام الأبيات */
.verse > .vno { color: var(--red); border-inline-end-color: color-mix(in srgb, var(--mud) 70%, transparent); }

/* ====== سمرقند — الزخرفة التيمورية ======
   لازوردٌ وذهبٌ وفيروز على عاجٍ. خلفية الصفحات (slots.pageBg) بلاطٌ نجميٌّ يطوّقها
   بلقطاتٍ بوردّاتٍ في الزوايا وقوسٍ محرابيٍّ لرقم الصفحة، وخلفية الغلاف (coverBg)
   بشمسةٍ في صدره ومروحة لوتسٍ في سفحه. زخرفة الأبواب من خانة h1Ornament والفاصل
   المرسوم من خانة separator. ملصق «التعليقات» ورأس الفهرس من ثلاث شرائح:
   طرفان ثابتان (٩٫٢مم لا يتضخّمان مهما طال النصّ) وبلاطٌ متكررٌ بالوسط (repeat-x)
   فتبقى معيّناته دائريةً مهما امتدّ العنوان، ولا يلمس النصُّ الحدودَ أبداً. */

/* الترويسة: نصٌّ داكنٌ دافئ بشعرةٍ ذهبيةٍ تحتها */
#book .rh { color: #4A3A1E; border-bottom: 0.5pt solid #C9A035; }

/* العناوين: الأبواب تعلو وتحتها زخرفةُ الخانة الذهبية
   (فرض الكتلة والعرض: الزخرفة المرسومة لا بدّ لها من مساحةٍ وإلا انكمشت.
   ونظام التقسيم «pro» يُخفي زينات عناوين الأبواب في وسمٍ يُحقن بعد الإضافات —
   فلا يُغنِ مساواةُ تحدُّه، ولذا رفعنا تحديدنا بـ.page ليتغلّب قهراً) */
#book .h1 { font-weight: 700; margin: 1mm 0 4mm; }
#book .h1::after,
#book .page .h.hs-part::after { display: block; width: 72mm; margin-inline: auto; }
#book .h2 { margin: 5.5mm 0 3mm; }
#book .h3, #book .h4 { margin: 4.5mm 0 2.4mm; }

/* رقم الصفحة في جوف القوس اللازوردي: حبرٌ ذهبيٌّ صافٍ وحده — لا رمزَ خلفه،
   وحبرُه مستوٍ مع الشريط السفلي تماماً (مركز صفّ المعيّنات ٦٫٢١مم من القاع؛
   القاعدة ٣٫٢مم لأن حبر الأرقام يعلو منتصف صندوق السطر بنصف مليّمٍ تقريباً) */
#book .folio { bottom: 3.2mm; font-size: 14pt; font-weight: 700; color: #C9A035; }

/* أرقام الأبيات في خانة يمين البيت: لازورد */
#book .vno { color: #16305F; }

/* — ملصق «التعليقات» ورأس الفهرس: شرائح لازوردية بحبرٍ ذهبيٍّ فاتح —
   (الوسط بلاطٌ متكررٌ لا ممدود، فلا تتشوّه المعيّنات مهما طال نصُّ العنوان) — */
#book .mc-below { margin-top: 4.5mm; }
#book .msep { display: none; }
#book .mc-label > span,
#book .page.mcom .mc-label > span,
#book .toc-hd > span {
  display: inline-block; padding: 1.6mm 11.2mm 2mm;
  background:
    asset(plat-r) right center / 9.2mm 100% no-repeat,
    asset(plat-l) left center / 9.2mm 100% no-repeat,
    asset(plat-m) center / auto 100% repeat-x;
}
/* في هامش المتن الجانبي يضيق العمود: طرفان أصغر لا يأكلان نصَّ العنوان */
#book .mc-side .mc-label > span {
  padding-inline: 8.4mm;
  background-size: 7mm 100%, 7mm 100%, auto 100%;
}

/* — الفهرس: رأسه في الملصق، وموضوعاته في خانةٍ بإطارٍ مزدوجٍ (لازورد خارجاً وذهبٌ داخلاً) — */
#book .page.toc .flow {
  background: #FFFDF6; border: 1pt solid #16305F; border-radius: 3mm;
  box-shadow: inset 0 0 0 0.45mm #C9A035;
  padding: 4mm 6mm 5mm;
}
#book .toc-hd { display: flex; justify-content: center; margin: 0 0 4mm; }
#book .toc-hd > span {
  font-family: var(--f-heading); font-weight: 700; font-size: 15pt; color: #F3E3AC;
}
#book .toc-cols {
  display: flex; justify-content: space-between; font-weight: 700; font-size: 11pt; color: #8F6D1C;
  margin: 0 1mm 2mm; border-bottom: 0.6pt solid #C9A035; padding-bottom: 1.3mm;
}
#book .toc-e { font-size: 13.5pt; }
#book .toc-e .ld { color: #C9A035; }

/* — الغلاف الداخلي: الشمسة في صدر الخلفية فجاء العنوان كبيراً للغاية (٣٦ و١٧ نقطة)
     تحتها، والبيانات في وسطٍ مرنٍ ينزاح إن طال العنوانُ بدل أن يصطدم به،
     وخانات الاسم والرقم أسفلها فوق مروحة اللوتس بإطارٍ مزدوجٍ لازورديٍّ ذهبيٍّ — */
.page.cover .body { top: 0; bottom: 0; left: 0; right: 0; }
.sm-cv { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; }
.sm-head {
  margin: 52mm 14% 0;
  display: flex; flex-direction: column; align-items: center; text-align: center;
  color: #16305F;
}
.sm-t { font-family: var(--f-cover); font-weight: 700; font-size: 36pt; line-height: 1.45; }
.sm-s { font-family: var(--f-cover); font-weight: 700; font-size: 17pt; line-height: 1.6; color: #9C2B2E; margin-top: 2mm; }
.sm-mid { margin-top: 24mm; display: flex; flex-direction: column; align-items: center; text-align: center; }
.sm-vol {
  font-family: var(--f-heading); font-weight: 700; font-size: 12pt; color: #8F6D1C;
  border-top: 0.6pt solid #C9A035; border-bottom: 0.6pt solid #C9A035;
  padding: 0.5mm 9mm; margin-bottom: 4.5mm;
}
/* الفاصل الزخرفي المرسوم (خانة separator) في وسط الغلاف
   (عرضٌ صريح: ابنُ عمودٍ بمحاذاة الوسط ينكمش إلى صفر مع خطّه المصفّر فتختفي خلفيته) */
#book .cv-orn { margin: 0 0 7mm; width: 52mm; }
.sm-lab { font-family: var(--f-heading); font-weight: 700; font-size: 12pt; color: #8F6D1C; margin-bottom: 1mm; }
.sm-name { font-family: var(--f-names); font-weight: 700; font-size: 22pt; line-height: 1.55; color: #16305F; }
.sm-name2 { font-size: 19pt; }
.sm-note { font-size: 11.5pt; color: #5A4A28; margin-top: 0.5mm; }
.sm-gap { height: 6mm; }
.sm-ed { font-size: 11pt; color: #5A4A28; margin-top: 5mm; }

/* — خانات الاسم والرقم: إطارٌ مزدوج (لازورد خارجاً وشعرةُ ذهبٍ داخلاً) تحتمل زيادة الخانات — */
.sm-cv .cv-owner {
  position: absolute; bottom: 26mm; left: 0; right: 0; width: 88mm; margin: 0 auto;
  display: flex; flex-direction: column; align-items: stretch; gap: 3.2mm;
  font-family: var(--f-heading); font-weight: 700; font-size: 13pt; color: #16305F;
}
.sm-cv .cv-of { display: flex; align-items: center; gap: 3mm; }
.sm-cv .cv-of .t { flex: none; }
.sm-cv .cv-of .f {
  flex: 1; height: 9mm; position: relative;
  border: 1pt solid #16305F; border-radius: 2.2mm; background: #FFFDF6;
  box-shadow: inset 0 0 0 0.4mm #C9A035;
}
.sm-cv .cv-of .f-dots::after { left: 2.6mm; right: 2.6mm; bottom: 2mm; border-bottom: 1.5pt dotted #8F6D1C; }
/* حبر خانات غلاف المتون التي يرسمها البرنامج بلونٍ آخر افتراضياً */
#book { --c-owner-ink: #16305F; }

/* ما يُكتب في الهوامش الجانبية والسفلى يبقى داخل الإطار وفوق القوس */
.page.content, .page.toc { --mside-edge: 11mm; --mside-bottom: 25mm; }

/* ===== الإطار: خطّان ونجمةٌ في كل زاوية (يصلح لأي مقاس ورق) ===== */
.page.content::before, .page.toc::before, .page.cover::before, .page.x-basmala::before {
  content: ''; position: absolute; inset: 8mm; pointer-events: none;
  border: 1.1pt solid var(--c-h1);
  outline: .4pt solid var(--c-orn); outline-offset: -1.8mm;
}
.page.content::after, .page.toc::after, .page.cover::after, .page.x-basmala::after {
  content: ''; position: absolute; inset: 4mm; pointer-events: none;
  background:
    asset(cstar) left top / 8mm 8mm no-repeat,
    asset(cstar) right top / 8mm 8mm no-repeat,
    asset(cstar) left bottom / 8mm 8mm no-repeat,
    asset(cstar) right bottom / 8mm 8mm no-repeat;
}
.page.content, .page.toc { --mside-edge: 12.5mm; --mside-bottom: 25mm; }

/* ===== الترويسة ===== */
.rh { left: var(--t-l); right: var(--t-r); font-family: var(--f-heading); font-size: 10pt; color: var(--c-h2);
  border-bottom: .5pt solid var(--c-orn); padding-bottom: 1.4mm; }
.rh::after { content: ''; position: absolute; left: 50%; bottom: -1.1mm; width: 2.2mm; height: 2.2mm; margin-left: -1.1mm;
  background: var(--c-orn); transform: rotate(45deg); }

/* ===== رقم الصفحة في نجمة ===== */
.page.content .folio, .page.toc .folio { left: var(--t-l); right: var(--t-r); bottom: 11.5mm; }
.fo { display: inline-flex; align-items: center; justify-content: center; width: 11mm; height: 11mm;
  background: asset(star) center / 100% 100% no-repeat; color: var(--c-h1); font-size: 10pt; font-weight: 700; line-height: 1; }

/* ===== الباب: نجمةٌ بقرصٍ فيه رقمه ===== */
.h1 { text-align: center; padding-top: 14mm; margin: 0 0 10mm; }
.h1::after { display: none; }
#book.no-newpage .h1 { padding-top: 2mm; margin-top: 9mm; }
.bb-star { position: relative; width: 24mm; height: 24mm; margin: 0 auto 5mm; display: flex; align-items: center; justify-content: center; }
.bb-star::before, .bb-star::after { content: ''; position: absolute; left: 3.5mm; top: 3.5mm; width: 17mm; height: 17mm;
  box-sizing: border-box; background: var(--c-h1); border: .9pt solid var(--c-orn); }
.bb-star::after { transform: rotate(45deg); }
.bb-star span { position: relative; z-index: 1; width: 11.5mm; height: 11.5mm; box-sizing: border-box;
  border: .7pt solid var(--c-orn); border-radius: 50%; display: flex; align-items: center; justify-content: center;
  color: #fff; font-size: 14pt; line-height: 1; }
.bb-t { line-height: 1.5; }
.bb-r { position: relative; width: 50mm; height: 0; margin: 4.5mm auto 0; border-top: .8pt solid var(--c-orn); }
.bb-r::after { content: ''; position: absolute; left: 50%; top: -1.3mm; width: 2.2mm; height: 2.2mm; margin-left: -1.1mm;
  background: var(--c-orn); transform: rotate(45deg); }

/* ===== الفصل والفرعي ===== */
.h2 { text-align: center; margin: 7mm 0 4mm; }
.h2::before, .h2::after { content: ''; display: inline-block; width: 1.8mm; height: 1.8mm; margin: 0 3mm;
  background: var(--c-orn); transform: rotate(45deg); vertical-align: middle; }
.h3 { margin: 5mm 0 2.5mm; padding-bottom: .8mm; border-bottom: .6pt dotted var(--c-rule); }
.h3::before { content: ''; display: inline-block; width: 1.6mm; height: 1.6mm; margin-inline-end: 2.5mm;
  background: var(--c-orn); transform: rotate(45deg); vertical-align: middle; }
.h4 { font-weight: 700; margin: 4mm 0 2mm; }
.ht { color: var(--c-h3); }

/* ===== الفاصل الزخرفي ===== */
.sep { text-align: center; margin: 3mm 0; }
.sep img { display: block; margin: 0 auto; width: 48mm; height: 4.8mm; }

/* ===== المتن: شريطٌ جانبي وتظليلٌ خفيف ===== */
.p.mt { padding: 0 4mm; border-inline-start: 2.4pt solid var(--c-matn);
  background: color-mix(in srgb, var(--c-matn) 4.5%, var(--paper)); }

/* ===== الحواشي ===== */
.fnsep { position: relative; width: 34%; height: 0; border: 0; border-top: .6pt solid var(--c-rule); background: none; }
.fnsep::after { content: ''; position: absolute; top: -1.2mm; right: 0; width: 1.8mm; height: 1.8mm;
  background: var(--c-orn); transform: rotate(45deg); }
.fnn, .fr { color: var(--c-h1); font-weight: 700; }

/* ===== الفهرس ===== */
.toc-title { color: var(--c-h1); text-align: center; }
.toc-rule { position: relative; width: 50mm; height: 0; margin: 3mm auto 6mm; border: 0; border-top: .8pt solid var(--c-orn); background: none; }
.toc-rule::after { content: ''; position: absolute; left: 50%; top: -1.3mm; width: 2.2mm; height: 2.2mm; margin-left: -1.1mm;
  background: var(--c-orn); transform: rotate(45deg); }
.toc-e.l1 { color: var(--c-h1); font-weight: 700; }
.toc-e.l2 { color: var(--c-h2); }

/* ===== الجداول ===== */
table.tbl th { background: color-mix(in srgb, var(--c-h1) 10%, var(--paper)); color: var(--c-h1); }

/* ===== فاصل الشطرين في الأبيات ===== */
.verse .vsep:not(.vmid) { display: inline-block; width: 1.5mm; height: 1.5mm; margin: 0 4mm; font-size: 0; color: transparent;
  background: var(--c-orn); transform: rotate(45deg); }

/* ===== الغلاف الداخلي ===== */
.page.cover .cover-frame { border-color: transparent !important; box-shadow: none; }
.cv-title { font-family: var(--f-cover); color: var(--c-h1); }
.cv-title::before { content: ''; display: block; width: 30mm; height: 30mm; margin: 0 auto 4mm;
  background: asset(rosette) center / 100% 100% no-repeat; }
.cv-sub { color: var(--c-h2); }
.cv-label { color: var(--c-h2); }
.cv-author, .cv-editor { font-family: var(--f-names); color: var(--c-h2); }
.cv-orn { display: block; font-size: 0; line-height: 0; color: transparent; width: 52mm; height: 5.2mm; margin: 3mm auto;
  background: asset(sep) center / 100% 100% no-repeat; }

/* خانات صاحب النسخة: الغلاف يضيق ليسعها */
.cv-owner { border-top: .6pt solid var(--c-rule); padding-top: 4mm; }
.page.cover.has-owner .cv-title { font-size: 24pt; }
.page.cover.has-owner .cv-title::before { width: 20mm; height: 20mm; margin-bottom: 3mm; }
.page.cover.has-owner .cv-orn { margin: 1.5mm auto; }

/* ===== المتون ===== */
.mc-label > span { display: inline-block; padding: 0 2mm .8mm; border-bottom: .8pt solid var(--c-orn); }
.mc-label > span::before, .mc-label > span::after { content: ''; display: inline-block; width: 1.6mm; height: 1.6mm; margin: 0 2.5mm;
  background: var(--c-orn); transform: rotate(45deg); vertical-align: middle; }
.msep { height: 0; border: 0; border-top: 1.2pt dotted var(--c-orn); background: none; }
.mintro { margin: 0 0 2.4mm; }
.mintro > span { background: color-mix(in srgb, var(--c-orn) 14%, var(--paper)); border: .4pt solid var(--c-orn);
  padding: .4mm 4mm .8mm; border-radius: 2mm; }

/* ===== خانة الهامش: خطّان ولسانٌ نجميّ يشير إلى النص ===== */
#book .mside-n.framed { padding: 2mm 2.6mm 1.8mm; border: .5pt solid var(--c-orn); border-radius: 0;
  background: color-mix(in srgb, var(--c-orn) 8%, var(--paper));
  box-shadow: inset 0 0 0 .6mm var(--paper), inset 0 0 0 .85mm var(--c-orn); }
#book .mside-n.framed::after { content: ''; position: absolute; top: 2mm; width: 3.2mm; height: 3.2mm;
  background: asset(cstar) center / 100% 100% no-repeat; }
#book .mside-n.framed.l::after { right: -1.9mm; }
#book .mside-n.framed.r::after { left: -1.9mm; }

/* ===== صفحة البسملة ===== */
.bsm { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 7mm; text-align: center; padding: 0 28mm; }
.bsm-rose { width: 82mm; height: 82mm; display: block; }
.bsm-t { font-family: 'Aref Ruqaa', serif; font-size: 34pt; font-weight: 700; color: var(--c-h1); line-height: 1.5; }
.bsm-sep { width: 56mm; height: 5.6mm; display: block; }
.bsm-b { font-family: var(--f-cover); font-size: 21pt; color: var(--c-h2); line-height: 1.5; }
.bsm-a { font-family: var(--f-names); font-size: 15pt; color: var(--c-text); }
